schemas.schema-01-systematic.prisma:
/// Discussion Board Category - Implements category management and administration from requirements.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Category name. Unique, used to group topics.
  name String

  /// Optional details about the category's use or scope.
  description String?

  /// Self-reference for hierarchy. Null for top-level categories.
  parent_id String? @db.Uuid

  /// Is the category currently enabled for participation?
  is_active Boolean

  /// Creation timestamp for this category row.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for this row.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_moderators discussion_board_category_moderators[]
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_system_notices discussion_board_system_notices[]
  discussion_board_topics discussion_board_topics[]

  @@unique([name])
  @@index([is_active])
  @@index([created_at])
}

/// Discussion Board persistent settings table for board-level options and toggles.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Setting key, e.g., 'registration_open'. Must be unique.
  setting_key String

  /// Value of the setting. Text-based for flexibility.
  setting_value String

  /// Optional description of what this setting controls.
  description String?

  /// Creation timestamp for this setting row.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for this row.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([setting_key])
  @@index([created_at])
}

/// Junction table mapping moderators to categories for M:N relationship per requirements. Each assignment is unique per (category_id, moderator_id).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_category_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to discussion_board_categories.id.
  category_id String @db.Uuid

  /// Reference to discussion_board_moderators.id (from Actors schema).
  moderator_id String @db.Uuid

  /// Assignment event creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_moderators_category_id_fkey discussion_board_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)
  discussion_board_category_moderators_moderator_id_fkey discussion_board_moderators @relation(fields: [moderator_id], references: [id], onDelete: Cascade)

  @@unique([category_id, moderator_id], map: "discussion_board_category_moderators_category_id_moder_8a76bb8d")
  @@index([category_id])
  @@index([moderator_id])
}

/// System auditing log for key events (config changes, assignments, bans, etc.). Append-only. Used for compliance and troubleshooting.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// ID (UUID) of actor (admin/moderator/member/user) who performed the event. Null for system actions.
  actor_id String? @db.Uuid

  /// Generic target object id affected by the action. Null if not applicable.
  target_id String? @db.Uuid

  /// Type of action performed (e.g., 'assign_moderator').
  action_type String

  /// Additional details or context for the event. Null if not given.
  action_detail String?

  /// Event timestamp for the audit log entry.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_audit_logs_actor_id_fkey discussion_board_admins? @relation(fields: [actor_id], references: [id], onDelete: Cascade)
  discussion_board_audit_logs_target_id_fkey discussion_board_categories? @relation(fields: [target_id], references: [id], onDelete: Cascade)

  @@index([actor_id])
  @@index([target_id])
  @@index([created_at])
  @@index([action_type(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System notices/messages for all or selected users (e.g., banners, important updates, system-wide or per-category, possibly scheduled).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_system_notices {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Optional reference to discussion_board_categories.id. Null means global notice.
  category_id String? @db.Uuid

  /// Notice headline/title.
  title String

  /// Message content for the notice.
  body String

  /// Is the notice currently displayed/shown?
  is_active Boolean

  /// Optional start date for scheduling visible time. Null = always until end_at.
  start_at DateTime? @db.Timestamptz

  /// Optional end date for scheduling end of visibility. Null = indefinite.
  end_at DateTime? @db.Timestamptz

  /// Creation time for audit/history.
  created_at DateTime @db.Timestamptz

  /// Last updated time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_system_notices_category_id_fkey discussion_board_categories? @relation(fields: [category_id], references: [id], onDelete: Cascade)

  @@index([is_active])
  @@index([category_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Discussion Board Admins - This implements the requirement for full-platform control and high-level configuration as described in roles and permissions requirements. 
///
/// Admins manage the system's configuration, assign or revoke moderation privileges, configure categories, and have access to analytics, audit logs, and sensitive management features. Maintains 3NF compliance by isolating admin-specific data from other actor roles. For example, when a new admin is registered or an existing member is promoted, a single record is created here with responsible actor and relevant timestamps. 
///
/// Key relationships: Typically references a user identity core record (external) and logs role-specific metadata. 
/// Special behaviors: Only records in this table may alter board configuration or perform overarching system management actions.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each admin actor instance.
  id String @id @db.Uuid

  /// User identifier - Implements the admin mapping aspect from requirements. The business user (system-wide or external reference, e.g., email or UID) that this admin role is assigned to. Ensures normalization by storing a single atomic identifier. For example, the platform user's UUID or SSO ID. Cannot be null.
  user_identifier String

  /// Grant timestamp - Represents when admin privileges were assigned. This supports audit trails, ensuring full actor traceability. For example, when a user is promoted, this is set to current timestamp.
  granted_at DateTime @db.Timestamptz

  /// Revocation timestamp - If admin rights are rescinded, this records when. Normalization ensures separation from business data—no status flags, just event time. For example, set when admin demotion is processed. Nullable (current if null).
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_moderation_actions discussion_board_moderation_actions[]
  discussion_board_content_flags discussion_board_content_flags[]

  @@unique([user_identifier])
  @@index([granted_at])
  @@index([revoked_at])
}

/// Discussion Board Moderators - Fulfills the requirement for stewardship, moderation, and enforcement powers outlined in the business requirements. 
///
/// Stores data on platform-approved moderators who manage flagged content, enforce rules, and resolve user reports. Maintains 3NF: Contains only moderator-specific role/temporal status info, not general user info.
///
/// Usage: When an admin appoints a user as moderator, this model is updated. Example: moderator is temporarily promoted, tracked by granted/revoked timestamps.
///
/// Key relationships: Should reference the user identity core record (external). Special behaviors: Only these users may moderate board content. Moderator history allows for temporary appointments and role audits.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the moderator role assignment.
  id String @id @db.Uuid

  /// User identifier - Implements role actor mapping. Identifies which user has moderator privilege. Ensures a flexible mapping to central user/auth system. Example: contains user UUID. Non-nullable.
  user_identifier String

  /// Role grant timestamp - Implements time-based access control for moderators. Defines when privilege started. Ensures normalized audit trail: e.g., moderating user granted the role on this date.
  granted_at DateTime @db.Timestamptz

  /// Role revocation timestamp - Supports time-boxed moderator roles and historical traceability for audit. Null if moderator powers still active. Example: removed when privilege is lost or user is demoted. Nullable.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_moderators discussion_board_category_moderators[]
  discussion_board_moderation_actions discussion_board_moderation_actions[]
  discussion_board_content_flags discussion_board_content_flags[]

  @@unique([user_identifier])
  @@index([granted_at])
  @@index([revoked_at])
}

/// Discussion Board Members - This captures all active registered users per system requirements. Implements business requirement for authenticated users with member privileges who can post, comment, report, and otherwise participate fully on the board.
///
/// Is strictly 3NF: contains only what is unique/relevant to the member role, not detailed user data or computed features. For example, a new member record is created upon registration or promotion from guest status.
///
/// Key relationships: May reference external user directory/identity tables.
/// Special behaviors: Additional flags/elevation handled via role-specific models (admin, moderator, etc.). Only users listed here may create threads or comments.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for registered member record.
  id String @id @db.Uuid

  /// User identifier - Implements member-account mapping to platform-wide or external user. Ensures atomic mapping to user identity. Example: could be user UUID, email, SSO subject. Non-nullable.
  user_identifier String

  /// Join timestamp - When the member registered on the board. Enables user analytics/audit logging. For example, set to creation date for analytics use.
  joined_at DateTime @db.Timestamptz

  /// Suspension timestamp - If the member is barred from participation, logs when suspension took effect. Normalized: retains only the timestamp, not pre-calculated status. Null if active.
  suspended_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_topics discussion_board_topics[]
  discussion_board_threads discussion_board_threads[]
  discussion_board_posts discussion_board_posts[]
  discussion_board_post_versions discussion_board_post_versions[]
  discussion_board_post_attachments discussion_board_post_attachments[]
  discussion_board_comments discussion_board_comments[]
  discussion_board_comment_versions discussion_board_comment_versions[]
  discussion_board_comment_attachments discussion_board_comment_attachments[]
  discussion_board_reports discussion_board_reports[]
  discussion_board_subscriptions discussion_board_subscriptions[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_activity_logs discussion_board_activity_logs[]

  @@unique([user_identifier])
  @@index([joined_at])
  @@index([suspended_at])
}

/// Discussion Board Guests - Implements the requirement for unauthenticated users who may browse (but not act) on public content, as per business requirements. 
///
/// Stores session-level tracking for guests (cookies, tokens, or temporary IDs) to distinguish unique visitors, support analytics, or inform onboarding flows (e.g., one-time announcements).
///
/// 3NF: No computed access flags, just raw identity and time stamps. Example: new guest detected (session/cookie assignment) creates a record here for behavior tracking until registration.
///
/// Key relationships: Standalone design, with possible linkage to analytics/log tables.
/// Special behaviors: Only guests here are treated as unique browsers for basic auditing—no personal data unless promoted to member.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID for the tracked guest session.
  id String @id @db.Uuid

  /// Session identifier - Implements tracking of guest/visitor session via cookie/token/UUID. Ensures atomicity and normalizes identification for auditing/analytics. For example, a one-time session ID. Required for all guest sessions.
  session_identifier String

  /// First seen timestamp - When this guest was first detected by the system. For session analysis/onboarding optimization. Non-nullable.
  first_seen_at DateTime @db.Timestamptz

  /// Last seen timestamp - Last activity by this guest before exit or registration. Helps track unique visitors and session duration; normalized storage. Non-nullable.
  last_seen_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([session_identifier])
  @@index([first_seen_at])
  @@index([last_seen_at])
}

/// Discussion Board User Sessions - Fulfills the cross-role requirement for persistent login/session tracking to support authentication, session management, and traceability, as required by the technical/API documentation.
///
/// Manages every authenticated or tracked session (admin, moderator, member, or guest), enabling token-based authentication, session expiry, user-actor analytics, and auto-logout on privilege changes. Maintains 3NF: holds only direct session facts, not computed fields or summaries. Example: a user logs in, a session is created here with user and session info, plus expiry fields for security/audit logging.
///
/// Key relationships: Should reference user identifier (admin, moderator, member) or guest session. No other foreign keys—designed for compatibility with all actor types.
///
/// Special behaviors: Only these records define active sessions. Session termination/expiry and forced logout for security is enforced by updating or nulling the termination timestamp. Role/applicable features determined externally (not here).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the user/guest session.
  id String @id @db.Uuid

  /// Actor type - Group discriminator (e.g., 'admin', 'moderator', 'member', 'guest'). Implements cross-role session context, as required by session management documentation. Ensures normalization by direct storage; no duplication of other user data. Example: 'moderator'. Non-nullable.
  actor_type String

  /// Actor identifier - Implements session-to-user/guest linkage (contains user_identifier or session_identifier as per actor_type). Normalizes reference to actor record, following atomic data principles. Non-nullable.
  actor_identifier String

  /// Session token - Stores opaque session token (e.g., JWT, UUID, cookie) for authentication. Supports per-session tracking for forced logouts, API/request scoping. Normalization: only token string, never computed status. Example: a unique token generated at login. Non-nullable.
  session_token String

  /// Session creation timestamp - For session timeline, auditing, and active user tracking. Example: when login completes or guest arrives. Non-nullable.
  created_at DateTime @db.Timestamptz

  /// Session expiry timestamp - When session is set to expire; enables auto-logout, security enforcement, and short/long session analytics. Non-nullable.
  expires_at DateTime @db.Timestamptz

  /// Termination timestamp (logout/kicked/timeout) - Supports hard logouts, token revocation, audit trails for suspicious/revoked sessions. Normalized: timestamp only, nullable if not terminated yet. For example, updated on manual logout, role loss, or session timeout. Nullable.
  terminated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([session_token])
  @@index([created_at])
  @@index([actor_type, actor_identifier])
}

schemas.schema-03-articles.prisma:
/// Topics on the discussion board - Implements the requirements for topic and thread management from the Features & Workflow documentation, supporting the creation and organization of main discussion areas. This model allows users to see a list of topics, and admins/moderators to manage (pin, close, delete) topics. Maintains 3NF compliance by keeping only atomic, non-aggregated data with referential integrity for creator, category, and status. Key relationships: category (to discussion_board_categories) and creator (to discussion_board_members). Special behaviors: topics may be pinned, closed, or deleted; closure restricts new posts at thread level.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_topics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each topic.
  id String @id @db.Uuid

  /// Category association – References the parent category's {@link discussion_board_categories.id} for hierarchical topic organization.
  discussion_board_category_id String @db.Uuid

  /// Creator member – References the member's {@link discussion_board_members.id} who created the topic, needed for audit trail and permissions enforcement.
  creator_member_id String @db.Uuid

  /// Topic title - Short text for headline display. Atomic, normalized.
  title String

  /// Topic description - Provides summary or guidelines for the topic. Optional, can be null for brief topics.
  description String?

  /// Indicates if topic is pinned.
  pinned Boolean

  /// Indicates if topic is closed.
  closed Boolean

  /// Timestamp of topic creation.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to the topic.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category discussion_board_categories @relation(fields: [discussion_board_category_id], references: [id], onDelete: Cascade)
  creator_member discussion_board_members @relation(fields: [creator_member_id], references: [id], onDelete: Cascade)

  discussion_board_threads discussion_board_threads[]
  discussion_board_activity_logs discussion_board_activity_logs[]
  discussion_board_engagement_stats discussion_board_engagement_stats[]

  @@index([creator_member_id])

  @@unique([discussion_board_category_id, title])
  @@index([created_at])
  @@index([pinned])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Threads within a topic - Implements threaded sub-discussions for separate conversations under one topic. Each thread belongs to a topic, and to a creator member. Fully normalized. Closure of parent topic invalidates new threads/posts.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each thread.
  id String @id @db.Uuid

  /// Parent topic – References {@link discussion_board_topics.id}, linking thread to its top-level area.
  discussion_board_topic_id String @db.Uuid

  /// Thread starter – References the member's {@link discussion_board_members.id} who created the thread.
  creator_member_id String @db.Uuid

  /// Thread title - User-provided, atomic.
  title String

  /// Timestamp when thread created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update/modification.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  topic discussion_board_topics @relation(fields: [discussion_board_topic_id], references: [id], onDelete: Cascade)
  creator_member discussion_board_members @relation(fields: [creator_member_id], references: [id], onDelete: Cascade)

  discussion_board_posts discussion_board_posts[]
  discussion_board_activity_logs discussion_board_activity_logs[]

  @@index([creator_member_id])

  @@unique([discussion_board_topic_id, title])
  @@index([discussion_board_topic_id, created_at], map: "discussion_board_threads_discussion_board_topic_id_cre_1d94f0ec")
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Atomic posts in discussion threads - Implements posting and commenting functionality. Each post is an individual contribution to a thread and references its creator and thread. Designed for atomic, normalized content. Soft-deletion handled by deleted_at. No aggregation of comment count/etc.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each post.
  id String @id @db.Uuid

  /// Parent thread – References {@link discussion_board_threads.id}.
  discussion_board_thread_id String @db.Uuid

  /// Post author – References {@link discussion_board_members.id}.
  creator_member_id String @db.Uuid

  /// Post body - Markdown/atomic text. Not calculated.
  body String

  /// Edit status - True if post edited. Atomic flag, 3NF compliant.
  is_edited Boolean

  /// Time of post creation.
  created_at DateTime @db.Timestamptz

  /// Time of last update.
  updated_at DateTime @db.Timestamptz

  /// Deletion timestamp if soft-deleted. Nullable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread discussion_board_threads @relation(fields: [discussion_board_thread_id], references: [id], onDelete: Cascade)
  creator_member discussion_board_members @relation(fields: [creator_member_id], references: [id], onDelete: Cascade)

  discussion_board_post_versions discussion_board_post_versions[]
  discussion_board_post_attachments discussion_board_post_attachments[]
  discussion_board_comments discussion_board_comments[]
  discussion_board_reports discussion_board_reports[]
  discussion_board_moderation_actions discussion_board_moderation_actions[]
  discussion_board_content_flags discussion_board_content_flags[]
  discussion_board_activity_logs discussion_board_activity_logs[]

  @@index([creator_member_id])

  @@index([discussion_board_thread_id, created_at], map: "discussion_board_posts_discussion_board_thread_id_crea_bf476e65")
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Snapshots of post revisions (version history/audit) - Implements snapshot-based architecture for post edit tracking, supporting rollback and audit history. Each entry stores a snapshot of the post content and incrementing version number. No aggregation. Each version is linked to an editor and to the associated post.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_versions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique, immutable identifier for each versioned snapshot.
  id String @id @db.Uuid

  /// Target post – References {@link discussion_board_posts.id}.
  discussion_board_post_id String @db.Uuid

  /// Editor responsible for this version – References {@link discussion_board_members.id}.
  editor_member_id String @db.Uuid

  /// Version number - Starts at 1, increments per edit.
  version Int @db.Integer

  /// Snapshot of post content.
  body String

  /// Timestamp when version created.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  editor_member discussion_board_members @relation(fields: [editor_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, version], map: "discussion_board_post_versions_discussion_board_post_i_bcb5ae9c")
  @@index([editor_member_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Attachment files for posts - Stores pure file/link metadata with reference to its post. Files are stored externally as URIs. Soft deletes handled via post or by removing external file, not by field aggregation. Each attachment links to both the post and uploader member.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each attachment.
  id String @id @db.Uuid

  /// Associated post – References {@link discussion_board_posts.id}.
  discussion_board_post_id String @db.Uuid

  /// Uploader – References {@link discussion_board_members.id}.
  uploader_member_id String @db.Uuid

  /// Location of the attachment file (external or CDN URI). Atomic, normalized.
  file_uri String @db.VarChar(80000)

  /// Original file name. Plain text, atomic.
  file_name String

  /// Attachment MIME type. E.g., 'image/png'.
  mime_type String

  /// Timestamp when file uploaded. Atomic event.
  uploaded_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  uploader_member discussion_board_members @relation(fields: [uploader_member_id], references: [id], onDelete: Cascade)

  @@index([discussion_board_post_id])
  @@index([uploader_member_id])

  @@index([uploaded_at])
}

schemas.schema-04-comments.prisma:
/// Comment Entity - This implements the persistent storage of all user-submitted comments in discussions, derived principally from the Posting and Commenting, Reporting, and Moderation requirements. Enables business: Members (authenticated users) can add comments to posts or threads, drive participation, and trigger moderation/reporting workflows. Maintains 3NF compliance by storing only basic comment data here, with version history and attachments managed by related tables. For example, a member posts a reply under a thread; this comment is stored here, and all edits spawn version records in discussion_board_comment_versions. Key relationships: References creator/member, post/thread, and version history. Special behaviors: Enforces logical deletion (soft delete), role-based permissions, and audit trails via related domain tables.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this comment entity instance, required for versioning, audit, and referencing from attachments, reports, or moderation actions.
  id String @id @db.Uuid

  /// Belonged member's {@link discussion_board_members.id} Identifies the member who created the comment. This links each comment to a registered member in the Actors domain. Ensures only authenticated users can create comments. For example, when 'JaneDoe' comments on a thread, discussion_board_member_id references her unique member id.
  discussion_board_member_id String @db.Uuid

  /// Target post's {@link discussion_board_posts.id} Associates comment with its parent post. Maintains comment thread context. For example, when commenting on a specific post in a topic, this points to the post id.
  discussion_board_post_id String @db.Uuid

  /// Current visible content of the comment - Implements base comment storage per Posting and Commenting requirements. Contains the editable text body at its most recent version. Ensures normalization by separating version history. For example, shows the latest text for all viewing users. Prohibited from containing calculation or aggregation data. Constraints: non-empty, max length per business rule.
  content String

