  //----
  // RELATIONS
  //----
  fk_comment_versions_comment discussion_board_comments @relation(fields: [discussion_board_comment_id], references: [id], onDelete: Cascade, map: "discussion_board_comment_versions_discussion_board_com_41b480cf")
