  //----
  // RELATIONS
  //----
  fk_comment_attachments_comment  discussion_board_comments @relation(fields: [discussion_board_comment_id], references: [id], onDelete: Cascade, map: "discussion_board_comment_attachments_discussion_board__f526cf2d")
  fk_comment_attachments_uploader discussion_board_members  @relation(fields: [uploader_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_comment_id, file_url], map: "discussion_board_comment_attachments_discussion_board__18b5d720")
  @@index([uploader_member_id, uploaded_at], map: "discussion_board_comment_attachments_uploader_member_i_c30b86ed")
}

schemas.schema-05-moderation.prisma:
/// Reports of inappropriate or abusive content - Tracks user reports of posts or comments that may violate guidelines. Maintains strict 3NF by separating each report as an atomic record. Polymorphic reference resolved by two nullable foreign keys: one for post and one for comment.
