import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching for discussion board admins using both active state and
 * grant date window filters.
 *
 * Business context: Admin listing and privilege audit panels must accurately
 * filter admins based on 'currently active' (revoked_at = null) and those whose
 * grant (assignment) happened in a specific period. This is essential for
 * compliance, privilege reviews, and behavioral analysis on the management
 * platform.
 *
 * Test steps:
 *
 * 1. Create several admin records with distinct grant/revoked_at timestamps:
 *
 *    - Some with revoked_at = null (active), others with revoked_at set (inactive)
 *    - Spread grant dates across a window before/during/after the filter period
 * 2. Formulate a search request with:
 *
 *    - Granted_at_from/granted_at_to spanning a window that covers only some created
 *         records
 *    - Revoked_at_from/revoked_at_to unset (not used in this test)
 * 3. Send the PATCH /discussionBoard/admin/admins request for search
 * 4. Assert:
 *
 *    - All returned admins are active (revoked_at is null)
 *    - All have grant (granted_at) inside the period (inclusive)
 *    - No extra records are present
 *    - Paging and data structure are as expected
 * 5. Edge: Test a second page if enough records exist (pagination)
 */
export async function test_api_discussionBoard_admin_admins_test_search_admins_by_active_state_and_granted_date_range(
  connection: api.IConnection,
) {
  // 1. Create admins with different states and grant/revoke dates
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 30); // 30 days ago
  const twentyDaysAgo = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 20); // 20 days ago
  const fifteenDaysAgo = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 15); // 15 days ago
  const tenDaysAgo = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 10); // 10 days ago

  // Create eligible admin: granted in filter, active
  const adminInFilterActive =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphabets(8),
        granted_at: twentyDaysAgo.toISOString(),
        revoked_at: null,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(adminInFilterActive);

  // Create ineligible admin: granted before filter window, active
  const adminBeforeFilterActive =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphabets(8),
        granted_at: thirtyDaysAgo.toISOString(),
        revoked_at: null,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(adminBeforeFilterActive);

  // Create ineligible admin: granted in filter, but revoked (inactive)
  const adminInFilterRevoked =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphabets(8),
        granted_at: fifteenDaysAgo.toISOString(),
        revoked_at: now.toISOString(),
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(adminInFilterRevoked);

  // Create ineligible admin: granted after filter window, active
  const adminAfterFilterActive =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphabets(8),
        granted_at: tenDaysAgo.toISOString(),
        revoked_at: null,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(adminAfterFilterActive);

  // 2. Search for active admins granted within filter window
  // Filter: granted_at_from = 20 days ago, granted_at_to = 15 days ago
  const grantedAtFrom = twentyDaysAgo.toISOString();
  const grantedAtTo = fifteenDaysAgo.toISOString();

  const searchResult = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        user_identifier: null,
        granted_at_from: grantedAtFrom,
        granted_at_to: grantedAtTo,
        revoked_at_from: null,
        revoked_at_to: null,
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(searchResult);

  // 3. Assert that all returned admins are active AND within grant window
  for (const admin of searchResult.data) {
    TestValidator.equals("revoked_at is null")(admin.revoked_at)(null);
    TestValidator.predicate("granted_at in filter window")(
      admin.granted_at >= grantedAtFrom && admin.granted_at <= grantedAtTo,
    );
  }

  // 4. Assert pagination
  TestValidator.equals("page is 1")(searchResult.pagination.current)(1);
  TestValidator.equals("limit is 100")(searchResult.pagination.limit)(100);
  TestValidator.predicate("pages positive")(searchResult.pagination.pages > 0);
  TestValidator.predicate("records nonnegative")(
    searchResult.pagination.records >= searchResult.data.length,
  );

  // 5. Only the eligible admin should be present
  const expectedUids = [adminInFilterActive.user_identifier];
  TestValidator.equals("returned count")(searchResult.data.length)(
    expectedUids.length,
  );
  for (const rec of searchResult.data) {
    TestValidator.predicate("data expected")(
      expectedUids.includes(rec.user_identifier),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the search functionality for admin users by partial match on
 * user_identifier (e.g., email, SSO ID).
 *
 * This test covers backend admin panel scenarios such as quick lookup, audits,
 * and record verification by fragments of user_identifier.
 *
 * 1. Create several admin records with overlapping user_identifier fragments
 *    (e.g., 'alice.admin01@company.com', 'alice.admin02@company.com',
 *    'alice.auditor@company.com', 'bob.admin@company.com').
 * 2. Perform a PATCH search using a partial string (e.g., 'alice.') as
 *    user_identifier.
 * 3. Confirm that all admins whose user_identifier includes the search fragment
 *    are returned, and only those.
 * 4. Test that pagination works (limit, page), and ordering matches input order if
 *    relevant.
 * 5. Verify that searching with a non-matching fragment returns an empty result
 *    set.
 */
export async function test_api_discussionBoard_admin_admins_test_search_admins_by_user_identifier_partial_match(
  connection: api.IConnection,
) {
  // 1. Create several admin records with known-overlap identifiers
  const now = new Date().toISOString();
  const adminInputs = [
    { user_identifier: "alice.admin01@company.com", granted_at: now },
    { user_identifier: "alice.admin02@company.com", granted_at: now },
    { user_identifier: "alice.auditor@company.com", granted_at: now },
    { user_identifier: "bob.admin@company.com", granted_at: now },
  ];
  const createdAdmins = [];
  for (const input of adminInputs) {
    const admin = await api.functional.discussionBoard.admin.admins.create(
      connection,
      {
        body: {
          ...input,
          revoked_at: null,
        } satisfies IDiscussionBoardAdmin.ICreate,
      },
    );
    typia.assert(admin);
    createdAdmins.push(admin);
  }

  // 2. Search for user_identifier containing 'alice.'
  const searchFragment = "alice.";
  const searchResult = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        user_identifier: searchFragment,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(searchResult);
  // Filter local source for matching expectations
  const expected = createdAdmins.filter((a) =>
    a.user_identifier.includes(searchFragment),
  );
  // Match found records (ids) exactly
  const returnedIds = searchResult.data.map((r) => r.id).sort();
  const expectedIds = expected.map((a) => a.id).sort();
  TestValidator.equals("matched ids")(returnedIds)(expectedIds);

  // 3. Test pagination: limit = 2
  const pagedResult = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        user_identifier: searchFragment,
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(pagedResult);
  TestValidator.equals("pagination limit")(pagedResult.data.length)(2);
  TestValidator.equals("pagination total")(pagedResult.pagination.records)(
    expected.length,
  );

  // 4. Searching with a fragment that matches none
  const noMatchResult =
    await api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        user_identifier: "zzz.notfound",
      } satisfies IDiscussionBoardAdmin.IRequest,
    });
  typia.assert(noMatchResult);
  TestValidator.equals("empty match set")(noMatchResult.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Retrieve a single board administrator's details by UUID and verify data
 * integrity.
 *
 * This test ensures the admin info retrieval endpoint works as intended for
 * permission and compliance workflows:
 *
 * 1. Create a discussion board admin entry (with unique user_identifier,
 *    granted_at, and possibly revoked_at).
 * 2. Retrieve the created admin entity using its id via GET
 *    `/discussionBoard/admin/admins/{adminId}`.
 * 3. Assert that all returned information (id, user_identifier, granted_at,
 *    revoked_at) matches what was submitted at creation, verifying correct
 *    persistence and retrieval.
 *
 * Steps:
 *
 * 1. Prepare a unique user_identifier and grant timestamp; revoked_at may be null
 *    or a specific datetime.
 * 2. Create admin via POST `/discussionBoard/admin/admins`.
 * 3. GET the admin by ID using `/discussionBoard/admin/admins/{adminId}`.
 * 4. Assert equality of the returned object's fields with those used at creation.
 */
export async function test_api_discussionBoard_admin_admins_test_get_admin_by_id_when_admin_exists(
  connection: api.IConnection,
) {
  // 1. Prepare a unique user_identifier, grant timestamp, and possibly revoked_at
  const now = new Date().toISOString();
  const userIdentifier = `audit_test_admin_${now}`;
  const adminInput: IDiscussionBoardAdmin.ICreate = {
    user_identifier: userIdentifier,
    granted_at: now,
    revoked_at: null,
  };

  // 2. Create the admin
  const created: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: adminInput,
    });
  typia.assert(created);
  TestValidator.equals("user_identifier matches")(created.user_identifier)(
    userIdentifier,
  );
  TestValidator.equals("granted_at matches")(created.granted_at)(now);
  TestValidator.equals("revoked_at matches null")(created.revoked_at)(null);

  // 3. Retrieve the created admin by id
  const retrieved: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: created.id,
    });
  typia.assert(retrieved);

  // 4. Assert all fields match creation
  TestValidator.equals("id matches")(retrieved.id)(created.id);
  TestValidator.equals("user_identifier matches")(retrieved.user_identifier)(
    userIdentifier,
  );
  TestValidator.equals("granted_at matches")(retrieved.granted_at)(now);
  TestValidator.equals("revoked_at matches null")(retrieved.revoked_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test proper error handling and data isolation when trying to retrieve a
 * non-existent board administrator by UUID.
 *
 * This test validates that when a client requests an admin by a UUID that does
 * not exist (e.g., random or deleted), the API MUST NOT leak any data about
 * other admins and MUST respond with a 404 or appropriate error. This is
 * important for privileged roles to prevent information disclosure about admin
 * assignments.
 *
 * Step-by-step:
 *
 * 1. Generate a random UUID intended not to match any current admin record
 *    (simulate a non-existent adminId).
 * 2. Attempt to fetch the admin entity by this adminId, using the GET
 *    /discussionBoard/admin/admins/{adminId} endpoint.
 * 3. Confirm that the API response is a proper 404 error (e.g., HttpError, or
 *    check for error object), NOT a valid entity.
 * 4. Ensure no data about any actual admin records are present in the error
 *    response.
 */
export async function test_api_discussionBoard_test_get_admin_by_id_not_found_error(
  connection: api.IConnection,
) {
  // 1. Generate a fake adminId (UUID not used by any admin)
  const randomAdminId = typia.random<string & tags.Format<"uuid">>();

  // 2-3. Attempt to fetch the admin and expect a 404 error (not found)
  await TestValidator.error("should return 404 for non-existent adminId")(
    async () => {
      await api.functional.discussionBoard.admin.admins.at(connection, {
        adminId: randomAdminId,
      });
    },
  );

  // 4. There should be no data leakage about other admins;
  //    if error body is available, ensure it only contains error info (implicit as no entity is returned).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * [감사 로그 상세 조회 기능 검증]
 *
 * 이 테스트는 관리자(admin) 권한으로, 특정 감사 로그(audit log) 상세 정보를 정확하게 조회하는 절차를 검증합니다.
 *
 * [테스트 절차 및 비즈니스 컨텍스트 설명]
 *
 * 1. 관리자 자격으로 감사 로그(audit log) 엔트리를 1건 생성합니다. (actor_id 등 메타정보 포함)
 * 2. 생성된 감사 로그 엔트리의 id(auditLogId)를 획득합니다. (정상 UUID 채번 여부도 검증)
 * 3. 해당 id를 사용하여 감사 로그 상세 조회 API를 호출합니다.
 * 4. 응답 결과가 요청한 id의 감사 로그임을 확인하고, actor_id, action_type, created_at 등 핵심 필드값이 모두
 *    보존되어 있는지, 정보 누락 없이 반환되는지 검증합니다.
 * 5. API 응답 타입 및 데이터 스키마가 실제 반환값과 일치하는지 typia.assert()로 반복 검증합니다.
 *
 * 이 테스트는 실제 관리/감사 환경에서 보안 감사 이력, 정책 변경 추적, 위임 등 중요한 이벤트에 대한 감사 로그의 신뢰성 및 상세 제공
 * 여부를 보장하기 위해 필요합니다.
 */
export async function test_api_discussionBoard_admin_auditLogs_test_retrieve_existing_audit_log_by_id_with_valid_admin_role(
  connection: api.IConnection,
) {
  // 1. 감사 로그 엔트리 신규 생성 (필수 actor_id, action_type 등 포함)
  const createBody: IDiscussionBoardAuditLog.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    target_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "assign_moderator", // 실제 용도 적합한 예시 액션명
    action_detail: "카테고리 관리자 권한 위임",
  };
  const created: IDiscussionBoardAuditLog =
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: createBody,
    });
  typia.assert(created);
  TestValidator.equals("생성 후 id 형식")(typeof created.id)("string");

  // 2. 생성된 감사 로그 id로 상세 조회 요청
  const fetched: IDiscussionBoardAuditLog =
    await api.functional.discussionBoard.admin.auditLogs.at(connection, {
      auditLogId: created.id,
    });
  typia.assert(fetched);

  // 3. 조회 결과의 필수 핵심 메타 검증
  TestValidator.equals("id 일치")(fetched.id)(created.id);
  TestValidator.equals("actor_id 일치")(fetched.actor_id)(createBody.actor_id);
  TestValidator.equals("action_type 일치")(fetched.action_type)(
    createBody.action_type,
  );
  TestValidator.equals("action_detail 일치")(fetched.action_detail)(
    createBody.action_detail,
  );
  TestValidator.equals("target_id 일치")(fetched.target_id)(
    createBody.target_id,
  );
  TestValidator.predicate("created_at 타임스탬프 존재 여부")(
    !!fetched.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
