/**
 * Validate that retrieving an audit log by a nonexistent ID returns a not-found
 * error.
 *
 * This test confirms the API returns a 404 error or a descriptive not-found
 * response when an audit log is requested with a random or nonexistent UUID. It
 * ensures proper error handling and that no sensitive or internal information
 * is leaked in the response.
 *
 * Steps:
 *
 * 1. Generate a random UUID that does not correspond to any audit log record.
 * 2. Attempt to retrieve the audit log using this UUID as auditLogId.
 * 3. Validate that the API call throws an error (HttpError) with a 404 status or
 *    not-found semantics.
 * 4. Ensure the error does not include internal details or sensitive data (cannot
 *    explicitly check message content per requirements).
 */
export async function test_api_discussionBoard_test_retrieve_audit_log_with_nonexistent_id_returns_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID
  const nonexistentAuditLogId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Attempt to retrieve the audit log and expect a not-found error
  await TestValidator.error("Audit log not found should result in 404")(
    async () => {
      await api.functional.discussionBoard.admin.auditLogs.at(connection, {
        auditLogId: nonexistentAuditLogId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * [관리자 감사 로그 기록 성공 테스트]
 *
 * 본 테스트는 관리자 권한으로 /discussionBoard/admin/auditLogs 엔드포인트를 통해 유효한 감사 로그 생성 요청 시
 * 정상적으로 기록이 저장되고, 모든 시스템/입력 필드가 일관되게 반환되는지 검증합니다.
 *
 * 1. 감사 로그 입력 DTO를 actor_id, target_id, action_type, action_detail을 모두 포함하도록 임의
 *    데이터로 구성한다 (필수/선택 필드 모두 포함).
 * 2. AuditLogs.create API를 호출하여 로그 생성 요청을 수행한다.
 * 3. 반환 응답에 시스템 생성 필드(id, created_at 등)와 입력값이 모두 포함되고, 값이 정확히 반영되었는지 검증한다.
 * 4. 각 필드 타입 및 key 존재 여부, 값의 일치성(assert), 서버 생성 시스템 값 존재성도 확인한다.
 */
export async function test_api_discussionBoard_admin_auditLogs_create(
  connection: api.IConnection,
) {
  // 1. 임의 감사 로그 입력 데이터 구성 (필수+선택 모두)
  const input: IDiscussionBoardAuditLog.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    target_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "assign_moderator",
    action_detail: "커뮤니티 관리권한 위임 처리",
  };

  // 2. 감사 로그 생성 API 호출
  const output = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    { body: input },
  );
  typia.assert(output);

  // 3. 반환 필드 검증: id, created_at(ISO8601), 입력 필드 값 일치 확인
  TestValidator.predicate("id는 uuid이어야 함")(
    typeof output.id === "string" && /^[0-9a-fA-F\-]{36}$/.test(output.id),
  );
  TestValidator.predicate("created_at은 ISO8601이어야 함")(
    typeof output.created_at === "string" &&
      !isNaN(Date.parse(output.created_at)),
  );
  TestValidator.equals("actor_id 일치")(output.actor_id)(input.actor_id);
  TestValidator.equals("target_id 일치")(output.target_id)(input.target_id);
  TestValidator.equals("action_type 일치")(output.action_type)(
    input.action_type,
  );
  TestValidator.equals("action_detail 일치")(output.action_detail)(
    input.action_detail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * 감사 로그 생성시 필수 필드 유효성 검증 테스트 (타입 오류 없이 가능)
 *
 * 관리자 권한으로 감사 로그를 생성 시도할 때, 정상적인 형식(타입을 만족하는 입력값)에서는 요청이 성공하고, 선택 필드를 null 또는
 * undefined 등 허용하는 값으로 두었을 때도 시스템이 허용하는지 검증한다.
 *
 * 비즈니스적으로 반드시 필요한 필드(action_type 등)는 타입 시스템 상에서 이미 보장되므로, 불완전한 테스트(컴파일 타임에 걸리는
 * 테스트)는 생략한다.
 *
 * 테스트 흐름:
 *
 * 1. 최소 필수값만 입력하여 정상 생성(성공)
 * 2. 선택 필드를 모두 null로 전달해 생성(성공 및 null 체크)
 * 3. 모든 필드를 적정값으로 채워서 생성(성공 및 값 검증)
 */
export async function test_api_discussionBoard_admin_auditLogs_create_validation(
  connection: api.IConnection,
) {
  // 1. 필수 값만 입력 → 정상 생성
  const minimal = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "assign_moderator",
      },
    },
  );
  typia.assert(minimal);
  TestValidator.equals("action_type 값")(minimal.action_type)(
    "assign_moderator",
  );

  // 2. 선택 필드를 모두 null로 채워서 생성
  const nullCase = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "policy_change",
        actor_id: null,
        target_id: null,
        action_detail: null,
      },
    },
  );
  typia.assert(nullCase);
  TestValidator.equals("action_type 값")(nullCase.action_type)("policy_change");
  TestValidator.equals("actor_id null 체크")(nullCase.actor_id)(null);
  TestValidator.equals("target_id null 체크")(nullCase.target_id)(null);
  TestValidator.equals("action_detail null 체크")(nullCase.action_detail)(null);

  // 3. 모든 필드 입력 정상 생성
  const complete = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "user_ban",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        target_id: typia.random<string & tags.Format<"uuid">>(),
        action_detail: "반복적인 정책 위반으로 계정 정지 처리.",
      },
    },
  );
  typia.assert(complete);
  TestValidator.equals("action_type 매칭")(complete.action_type)("user_ban");
  TestValidator.equals("action_detail 매칭")(complete.action_detail)(
    "반복적인 정책 위반으로 계정 정지 처리.",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * Validate successful update of an audit log entry by admin.
 *
 * This test covers the full workflow of creating an audit log, updating it, and
 * verifying the changes and history for audit integrity.
 *
 * Steps:
 *
 * 1. Create a new audit log entry (using the admin endpoint).
 * 2. Update key fields of the entry by its id (e.g., action_detail, target_id).
 * 3. Assert updated fields reflect new values; unchanged fields remain consistent.
 * 4. Confirm system-managed fields (id, created_at) are not altered except as
 *    allowed.
 * 5. Ensure all changes are returned and traceable for audit compliance.
 */
export async function test_api_discussionBoard_admin_auditLogs_test_update_audit_log_event_by_id_successful_update(
  connection: api.IConnection,
) {
  // 1. Create a new audit log entry
  const createInput: IDiscussionBoardAuditLog.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    target_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "assign_moderator",
    action_detail: "Moderator assigned to category 1234 for policy compliance.",
  };
  const created: IDiscussionBoardAuditLog =
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Update audit log fields by id
  const updateInput: IDiscussionBoardAuditLog.IUpdate = {
    action_detail: "Moderator was updated to category 9999. See details.",
    target_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated: IDiscussionBoardAuditLog =
    await api.functional.discussionBoard.admin.auditLogs.update(connection, {
      auditLogId: created.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 3. Assert updated fields reflect new values
  TestValidator.equals("updated action_detail")(updated.action_detail)(
    updateInput.action_detail,
  );
  TestValidator.equals("updated target_id")(updated.target_id)(
    updateInput.target_id,
  );

  // 4. Assert unchanged fields remain consistent
  TestValidator.equals("id unchanged")(updated.id)(created.id);
  TestValidator.equals("action_type unchanged")(updated.action_type)(
    created.action_type,
  );
  TestValidator.equals("actor_id unchanged")(updated.actor_id)(
    created.actor_id,
  );

  // 5. Confirm system-managed fields (created_at) remain correct (not reversed/null)
  TestValidator.predicate("created_at retained and valid")(
    typeof updated.created_at === "string" && updated.created_at.length > 0,
  );
}

