      tags.Format<"date-time">,
    metadata_json: JSON.stringify({ reason: "moderator test log" }),
  };
  const activityLog: IDiscussionBoardActivityLog =
    await api.functional.discussionBoard.moderator.activityLogs.create(
      connection,
