  // 3. Generate random topic details
  const randomTitle = RandomGenerator.paragraph()(1); // Short random phrase to simulate a title
  const topicBody: IDiscussionBoardTopics.ICreate = {
    title: randomTitle,
    description: RandomGenerator.paragraph()(),
    pinned: false,
