import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";

/**
 * Validate admin access to complete version histories for comment editing.
 *
 * Scenario:
 *
 * 1. Register a new board member who will serve as the author of the comment.
 * 2. Register a second member who will serve as an unrelated user (for negative
 *    tests).
 * 3. As the author member, create a new comment (requires a valid postId).
 * 4. While impersonating the author, edit the comment multiple times—each edit
 *    creates a new version history.
 * 5. As an admin, retrieve all version histories for this comment and validate
 *    that snapshots are listed, editors match, and timestamps are
 *    chronological.
 * 6. For another newly created comment (with no edits), confirm version list is
 *    empty via the admin endpoint.
 * 7. Confirm that non-authorized users (such as the unrelated member) are denied
 *    access to the version list endpoint (expect error).
 */
export async function test_api_discussionBoard_test_list_all_versions_of_comment_for_admin(
  connection: api.IConnection,
) {
  // Step 1: Register an author member.
  const authorMember =
    await api.functional.discussionBoard.admin.members.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphaNumeric(10),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(authorMember);

  // Step 2: Register a random unrelated member (for negative access test).
  const outsiderMember =
    await api.functional.discussionBoard.admin.members.create(connection, {
      body: {
        user_identifier: RandomGenerator.alphaNumeric(10),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(outsiderMember);

  // Step 3: As the author member, create a comment with a unique post id.
  // (Assume the authorMember is authenticated for API context here.)
  const discussion_board_post_id = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: authorMember.id,
        discussion_board_post_id,
        content: RandomGenerator.paragraph()(10),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // Step 4: As author, perform 2 edits (create 2 more versions)
  const firstEdit =
    await api.functional.discussionBoard.member.comments.versions.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          editor_member_id: authorMember.id,
          content: RandomGenerator.paragraph()(5),
        } satisfies IDiscussionBoardCommentVersion.ICreate,
      },
    );
  typia.assert(firstEdit);

  const secondEdit =
    await api.functional.discussionBoard.member.comments.versions.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          editor_member_id: authorMember.id,
          content: RandomGenerator.paragraph()(7),
        } satisfies IDiscussionBoardCommentVersion.ICreate,
      },
    );
  typia.assert(secondEdit);

  // Step 5: As admin, fetch all versions for this comment
  const versionsPage =
    await api.functional.discussionBoard.admin.comments.versions.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(versionsPage);
  TestValidator.predicate("version data is not empty and ordered")(
    versionsPage.data.length >= 2 &&
      versionsPage.data.every(
        (v, idx, arr) =>
          idx === 0 ||
          Date.parse(arr[idx - 1].created_at) <= Date.parse(v.created_at),
      ),
  );
  // Check editor_member_id for each version
  for (const version of versionsPage.data) {
    TestValidator.equals("editor is author")(version.editor_member_id)(
      authorMember.id,
    );
  }

  // Step 6: Create a new comment (no edits) and check version list is empty
  const commentNoEdits =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_member_id: authorMember.id,
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        content: RandomGenerator.paragraph()(6),
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(commentNoEdits);
  const emptyVersions =
    await api.functional.discussionBoard.admin.comments.versions.index(
      connection,
      {
        commentId: commentNoEdits.id,
      },
    );
  typia.assert(emptyVersions);
  TestValidator.equals("no versions exist")(emptyVersions.data)([]);

  // Step 7: Attempt to fetch versions as unrelated/outsider member (should be denied)
  // (Assume switching context; here, just to demonstrate error expectation)
  await TestValidator.error("outsider cannot access versions")(async () => {
    // In practice, switching auth context needed; simulate by passing outsider id.
    // In real E2E, you would switch connection/auth context here.
    await api.functional.discussionBoard.admin.comments.versions.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 멤버의 자신의 댓글 버전 히스토리 필터/검색/페이지네이션 검증
 *
 * 이 테스트에서는 다음을 검증합니다:
 *
 * 1. 멤버가 댓글을 생성할 수 있다.
 * 2. 멤버가 댓글을 여러 번 수정하여 버전 히스토리를 남길 수 있다.
 * 3. 멤버가 자신이 작성한 댓글의 버전 히스토리를 editor, date, content 기준으로 검색/필터링할 수 있다.
 * 4. 버전 히스토리에 페이지네이션이 정상적으로 동작한다.
 * 5. Editor_member_id로 필터링 시 올바른 버전만 반환된다.
 * 6. Created_at_from/to, content_contains 필터로 적절한 결과값이 반환된다.
 * 7. 다른 멤버가 소유하지 않은 댓글의 버전 히스토리를 조회하면 권한 오류가 발생한다.
 *
 * [테스트 시나리오]
 *
 * 1. 두 개의 멤버(MemberA/B) UUID를 랜덤 생성(인증 API 미지원 → 시뮬)
 * 2. MemberA가 댓글 생성
 * 3. MemberA가 댓글을 여러 번 수정하여 버전 생성
 * 4. (MemberA) 버전 히스토리 전체 조회/에디터별/내용별/날짜별/페이지네이션 검증
 * 5. (MemberB) 타인의 댓글 버전 히스토리 조회 시 권한 오류 확인
 */
export async function test_api_discussionBoard_test_search_filter_and_paginate_comment_versions_for_member(
  connection: api.IConnection,
) {
  // 1. 두 회원 UUID 생성 (인증/세션이 없으므로 시뮬)
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  // 임의 게시글 UUID
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 2. MemberA 댓글 생성
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: memberAId,
        discussion_board_post_id: postId,
        content: "버전 기능 E2E 테스트용 최초 댓글",
      },
    },
  );
  typia.assert(comment);

  // 3. MemberA 댓글 수정 버전 여러 개 생성
  const versions: IDiscussionBoardCommentVersion[] = [];
  for (let i = 0; i < 3; ++i) {
    const content = `버전${i + 1} 멤버A ${RandomGenerator.alphaNumeric(6)}`;
    const version =
      await api.functional.discussionBoard.member.comments.versions.create(
        connection,
        {
          commentId: comment.id,
          body: {
            discussion_board_comment_id: comment.id,
            editor_member_id: memberAId,
            content,
          },
        },
      );
    typia.assert(version);
    versions.push(version);
  }

  // 4-1. 전체 버전(Unfiltered)
  const allResult =
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: {},
      },
    );
  typia.assert(allResult);
  TestValidator.equals("전체 버전 수")(allResult.data.length)(versions.length);

  // 4-2. editor_member_id로만 필터
  const filteredByEditor =
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: { editor_member_id: memberAId },
      },
    );
  typia.assert(filteredByEditor);
  for (const v of filteredByEditor.data) {
    TestValidator.equals("에디터 일치")(v.editor_member_id)(memberAId);
  }

  // 4-3. 내용 substring 필터(content_contains)
  const targetStr = versions[1].content.split(" ")[1]; // 생성한 랜덤 토큰 잡기
  const filteredByContent =
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: { content_contains: targetStr },
      },
    );
  typia.assert(filteredByContent);
  TestValidator.predicate("내용 substring 필터로 결과 1개 이상")(
    filteredByContent.data.length > 0,
  );
  for (const v of filteredByContent.data) {
    TestValidator.predicate("내용에 substring 포함")(
      v.content.includes(targetStr),
    );
  }

  // 4-4. 날짜 from~to
  const from = versions[0].created_at;
  const to = versions[versions.length - 1].created_at;
  const filteredByDate =
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: { created_at_from: from, created_at_to: to },
      },
    );
  typia.assert(filteredByDate);
  TestValidator.predicate("날짜 범위 필터 결과 1개 이상")(
    filteredByDate.data.length >= 1,
  );

  // 4-5. 페이지네이션(전체 records 수 연결 확인)
  const paginated =
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: {},
      },
    );
  typia.assert(paginated);
  TestValidator.equals("pagination 전체 수")(paginated.pagination.records)(
    versions.length,
  );

  // 5. MemberB가 타인 댓글 버전 히스토리 시도(권한오류 예상)
  TestValidator.error("MemberB 권한 오류")(async () => {
    await api.functional.discussionBoard.member.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: { editor_member_id: memberBId },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and pagination of a comment's version history by a
 * moderator.
 *
 * Ensures that:
 *
 * 1. A member creates a comment under a post.
 * 2. Multiple versions are created for that comment: by both the member (original
 *    author) and moderator (as editor).
 * 3. Moderator executes advanced search:
 *
 *    - Filter by editor_member_id (should only return moderator's edits)
 *    - Filter by date/time window (created_at_from/to)
 *    - Filter by content substring (content_contains)
 *    - Test presence/structure of pagination (cannot set limits explicitly as per
 *         DTO, but verifies structure)
 * 4. Validates that results returned match search criteria (editor/content/date).
 * 5. Ensures error is returned for invalid commentId, validated via
 *    TestValidator.error().
 */
export async function test_api_discussionBoard_test_moderator_advanced_search_on_comment_versions(
  connection: api.IConnection,
) {
  // 1. MEMBER creates a comment for a post
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const postId: string = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: memberId,
        discussion_board_post_id: postId,
        content: "Initial member comment content.",
      },
    },
  );
  typia.assert(comment);

  // 2. First version by member (simulate edit by member)
  const memberEditContent = "Member edit 1 content.";
  const memberEdit =
    await api.functional.discussionBoard.moderator.comments.versions.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          editor_member_id: memberId,
          content: memberEditContent,
        },
      },
    );
  typia.assert(memberEdit);

  // 3. Moderator creates two edit versions
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const modEditContent1 = "Moderator edit version 1";
  const modEdit1 =
    await api.functional.discussionBoard.moderator.comments.versions.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          editor_member_id: moderatorId,
          content: modEditContent1,
        },
      },
    );
  typia.assert(modEdit1);

  await new Promise((res) => setTimeout(res, 50));
  const modEditContent2 = "Moderator edit version 2";
  const modEdit2 =
    await api.functional.discussionBoard.moderator.comments.versions.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          editor_member_id: moderatorId,
          content: modEditContent2,
        },
      },
    );
  typia.assert(modEdit2);

  // 4. Search by editor_member_id (moderator)
  const searchByEditor =
    await api.functional.discussionBoard.moderator.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: {
          editor_member_id: moderatorId,
        },
      },
    );
  typia.assert(searchByEditor);
  const expectedModIds = [modEdit1.id, modEdit2.id];
  TestValidator.equals("only moderator version IDs returned")(
    new Set(searchByEditor.data.map((v) => v.id)),
  )(new Set(expectedModIds));

  // 5. Search by date window (from/to: only moderator's edits)
  const from = modEdit1.created_at;
  const to = modEdit2.created_at;
  const searchByTime =
    await api.functional.discussionBoard.moderator.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: {
          created_at_from: from,
          created_at_to: to,
        },
      },
    );
  typia.assert(searchByTime);
  TestValidator.predicate("versions in correct date range")(
    searchByTime.data.every(
      (ver) => ver.created_at >= from && ver.created_at <= to,
    ),
  );

  // 6. Search by content substring
  const substring = "edit version 1";
  const searchByContent =
    await api.functional.discussionBoard.moderator.comments.versions.search(
      connection,
      {
        commentId: comment.id,
        body: {
          content_contains: substring,
        },
      },
    );
  typia.assert(searchByContent);
  TestValidator.predicate("content substring present")(
    searchByContent.data.every((ver) => ver.content.includes(substring)),
  );

  // 7. Pagination response structure (cannot directly set page/limit via DTO, so just verify type/structure)
  TestValidator.equals("pagination type present")(
    typeof searchByEditor.pagination.current,
  )("number");

  // 8. Error: invalid commentId for search returns error
  await TestValidator.error("invalid commentId triggers error")(async () => {
    await api.functional.discussionBoard.moderator.comments.versions.search(
      connection,
      {
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {},
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
