import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IPageIDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSubscription";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates a member's ability to filter their own discussion board
 * subscriptions by various criteria using PATCH
 * /discussionBoard/member/subscriptions, ensuring scoping only returns that
 * member's subscriptions despite the presence of other users' subscriptions in
 * the system.
 *
 * This test proceeds as follows:
 *
 * 1. Create another member's subscriptions using the admin endpoint to seed
 *    unrelated data (simulate 'other users exist').
 * 2. As the target test member, create several subscriptions of both 'topic' and
 *    'thread' types, using various notification methods and active/inactive
 *    statuses.
 * 3. For each filter criteria (by target type, by notification method, by
 *    is_active):
 *
 *    - Issue a PATCH filter operation as the member
 *    - Ensure only subscriptions for the authenticated member are returned
 *    - Ensure the returned subscriptions match the specific filter used (type,
 *         notification_method, is_active)
 *    - Test edge case: apply a filter that should return zero results, confirm empty
 *         array
 * 4. Confirm pagination response shape is always valid.
 */
export async function test_api_discussionBoard_member_subscriptions_test_member_filter_own_subscriptions(
  connection: api.IConnection,
) {
  // 1. Create another member's subscriptions for access isolation test
  const otherMemberId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedSubscription =
    await api.functional.discussionBoard.admin.subscriptions.create(
      connection,
      {
        body: {
          subscriber_id: otherMemberId,
          target_type: "topic",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          notification_method: "email",
          is_active: true,
        } satisfies IDiscussionBoardSubscription.ICreate,
      },
    );
  typia.assert(unrelatedSubscription);

  // 2. Create multiple subscriptions for the authenticated member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  // In an actual system, proper authentication switching logic would be used for this member.
  // Here, only the subscriber_id value reflects intended test subject.
  const mySubs: IDiscussionBoardSubscription[] = await Promise.all([
    api.functional.discussionBoard.member.subscriptions.create(connection, {
      body: {
        subscriber_id: memberId,
        target_type: "topic",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        notification_method: "email",
        is_active: true,
      } satisfies IDiscussionBoardSubscription.ICreate,
    }),
    api.functional.discussionBoard.member.subscriptions.create(connection, {
      body: {
        subscriber_id: memberId,
        target_type: "thread",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        notification_method: "in-app",
        is_active: false,
      } satisfies IDiscussionBoardSubscription.ICreate,
    }),
    api.functional.discussionBoard.member.subscriptions.create(connection, {
      body: {
        subscriber_id: memberId,
        target_type: "topic",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        notification_method: "in-app",
        is_active: true,
      } satisfies IDiscussionBoardSubscription.ICreate,
    }),
  ]);
  mySubs.forEach((s) => typia.assert(s));

  // 3a. Filter by target_type (e.g. "topic")
  const typeFiltered =
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          target_type: "topic",
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  typia.assert(typeFiltered);
  TestValidator.predicate("type filter - only member's records")(
    typeFiltered.data.every(
      (s) => s.subscriber_id === memberId && s.target_type === "topic",
    ),
  );
  TestValidator.equals("type filter - count matches")(typeFiltered.data.length)(
    mySubs.filter((s) => s.target_type === "topic").length,
  );

  // 3b. Filter by notification_method (e.g. "in-app")
  const methodFiltered =
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          notification_method: "in-app",
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  typia.assert(methodFiltered);
  TestValidator.predicate("method filter - only member's records")(
    methodFiltered.data.every(
      (s) => s.subscriber_id === memberId && s.notification_method === "in-app",
    ),
  );
  TestValidator.equals("notification_method filter - count matches")(
    methodFiltered.data.length,
  )(mySubs.filter((s) => s.notification_method === "in-app").length);

  // 3c. Filter by is_active (true)
  const activeFiltered =
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          is_active: true,
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  typia.assert(activeFiltered);
  TestValidator.predicate("is_active filter - only member's active records")(
    activeFiltered.data.every(
      (s) => s.subscriber_id === memberId && s.is_active === true,
    ),
  );
  TestValidator.equals("is_active filter - count matches")(
    activeFiltered.data.length,
  )(mySubs.filter((s) => s.is_active === true).length);

  // 3d. Edge case: Apply a filter guaranteed to return no match
  const emptyFiltered =
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          target_type: "nonexistent",
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  typia.assert(emptyFiltered);
  TestValidator.equals("empty filter yields no data")(
    emptyFiltered.data.length,
  )(0);

  // 4. Validate structure of expected pagination for all responses
  [typeFiltered, methodFiltered, activeFiltered, emptyFiltered].forEach(
    (page) => {
      typia.assert(page.pagination);
      TestValidator.predicate("pagination current positive")(
        page.pagination.current > 0,
      );
      TestValidator.predicate("pagination limit positive")(
        page.pagination.limit > 0,
      );
      TestValidator.predicate("pagination records nonnegative")(
        page.pagination.records >= 0,
      );
      TestValidator.predicate("pagination pages positive")(
        page.pagination.pages > 0,
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IPageIDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSubscription";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that a regular member cannot access another user's subscriptions by
 * supplying a different user's UUID as the `subscriber_id` in the PATCH request
 * to /discussionBoard/member/subscriptions.
 *
 * The system must enforce that regular members can only query their own
 * subscriptions:
 *
 * - Searching for another member's subscriptions as a regular user (by specifying
 *   their UUID) should be forbidden (error thrown), or must not return any
 *   out-of-scope data (backend may choose error or just empty results).
 * - Searching with your own UUID should succeed and return only your
 *   subscriptions.
 *
 * **Process:**
 *
 * 1. Admin creates a subscription for a 'victim' user so there is a record to test
 *    against.
 * 2. As a regular member (the attacker), attempt to search for victim's
 *    subscriptions using victim's UUID.
 * 3. Confirm that either an error is thrown (forbidden), or no unauthorized data
 *    is revealed.
 * 4. Additionally, as the member, attempt to search your own subscriptions and
 *    confirm results only belong to self.
 *
 * **Assumption:** The `connection` parameter is authenticated as a regular
 * member (attacker), NOT as admin or victim. If authentication/role switching
 * is required, ensure proper steps precede these actions using actual
 * authentication APIs.
 */
export async function test_api_discussionBoard_test_forbidden_when_member_searches_other_users_subscriptions(
  connection: api.IConnection,
) {
  // 1. Setup: Admin creates a subscription for the victim user (so that there is data to attempt to access)
  const victimUserId: string = typia.random<string & tags.Format<"uuid">>();
  const topicId: string = typia.random<string & tags.Format<"uuid">>();

  const created: IDiscussionBoardSubscription =
    await api.functional.discussionBoard.admin.subscriptions.create(
      connection,
      {
        body: {
          subscriber_id: victimUserId,
          target_type: "topic",
          target_id: topicId,
          notification_method: "in-app",
          is_active: true,
        } satisfies IDiscussionBoardSubscription.ICreate,
      },
    );
  typia.assert(created);
  TestValidator.equals("subscription belongs to victim")(created.subscriber_id)(
    victimUserId,
  );

  // 2. As a regular member, attempt to search subscriptions for another user (should not be allowed)
  TestValidator.error(
    "regular member cannot list another user's subscriptions",
  )(async () => {
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          subscriber_id: victimUserId,
          limit: 5,
          page: 1,
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  });

  // 3. Additionally, search with your own user id (should be allowed; results, if any, must be owned by self)
  // In real setups, attackerUserId would be derived from authenticated member's profile.
  // For this e2e, just assign a random but realistic id (in real-case, fetch actual user id of connection).
  const attackerUserId: string = typia.random<string & tags.Format<"uuid">>();
  const selfSearch =
    await api.functional.discussionBoard.member.subscriptions.search(
      connection,
      {
        body: {
          subscriber_id: attackerUserId,
          limit: 5,
          page: 1,
        } satisfies IDiscussionBoardSubscription.IRequest,
      },
    );
  typia.assert(selfSearch);
  // 4. Validate all subscriptions (if any) are owned by the requester/attacker
  TestValidator.predicate("subscribed records are only owned by self")(
    selfSearch.data.every((x) => x.subscriber_id === attackerUserId),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test retrieval of all discussion board categories with default pagination as
 * a public endpoint.
 *
 * Validates that any guest or authenticated user can access the list of
 * discussion board categories without authentication. The categories should be
 * in a flat list format, including all relevant metadata (name, description,
 * parent-child linkage, activation status, and timestamps). No special setup or
 * dependencies are needed for this endpoint.
 *
 * Steps:
 *
 * 1. Call the GET /discussionBoard/categories endpoint using a minimal connection
 *    (no auth).
 * 2. Assert the response structure (IPageIDiscussionBoardCategory) is valid using
 *    typia.assert().
 * 3. For every category, validate metadata is complete:
 *
 *    - Id is a uuid
 *    - Name is defined and non-empty
 *    - Is_active is boolean
 *    - Created_at and updated_at follow ISO8601 'date-time' format
 *    - Parent_id is either null or a valid uuid (if present)
 * 4. Verify a mix of root and nested (has parent_id) categories are present in the
 *    data (if available).
 * 5. Cross-check that active/inactive categories are properly represented, if
 *    available.
 *
 * Edge cases: If the data contains only root or only inactive categories, log a
 * warning but do not fail the test. The main requirement is correct structure
 * and visibility without authentication.
 */
export async function test_api_discussionBoard_test_list_all_discussion_board_categories_default_pagination(
  connection: api.IConnection,
) {
  // Step 1: List all categories without authentication (public endpoint)
  const output =
    await api.functional.discussionBoard.categories.index(connection);
  typia.assert(output);

  // Step 2: Validate category metadata and structure
  for (const category of output.data) {
    // Check id (uuid)
    TestValidator.predicate(`category.id is uuid`)(
      typeof category.id === "string" &&
        /^[0-9a-fA-F-]{8}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{12}$/.test(
          category.id,
        ),
    );
    // Name exists and non-empty
    TestValidator.predicate(`category.name exists and is non-empty`)(
      typeof category.name === "string" && category.name.length > 0,
    );
    // Activation flag
    TestValidator.predicate(`category.is_active is boolean`)(
      typeof category.is_active === "boolean",
    );
    // Timestamp fields (ISO date-time)
    TestValidator.predicate(`category.created_at is ISO date-time string`)(
      typeof category.created_at === "string" &&
        !isNaN(Date.parse(category.created_at)),
    );
    TestValidator.predicate(`category.updated_at is ISO date-time string`)(
      typeof category.updated_at === "string" &&
        !isNaN(Date.parse(category.updated_at)),
    );
    // parent_id is either null, undefined, or valid uuid (if present)
    if (category.parent_id !== undefined && category.parent_id !== null)
      TestValidator.predicate(`category.parent_id is uuid (if exists)`)(
        typeof category.parent_id === "string" &&
          /^[0-9a-fA-F-]{8}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{4}-[0-9a-fA-F-]{12}$/.test(
            category.parent_id,
          ),
      );
  }

  // Step 3: Coverage verification for root/nested categories and activation
  const hasRoot = output.data.some(
    (cat) => cat.parent_id === null || cat.parent_id === undefined,
  );
  const hasNested = output.data.some(
    (cat) => typeof cat.parent_id === "string",
  );
  const hasInactive = output.data.some((cat) => cat.is_active === false);
  if (!hasRoot)
    console.warn(
      "[e2e] No root categories were found. Check seed data setup if needed.",
    );
  if (!hasNested)
    console.warn(
      "[e2e] No nested categories (parent_id) were found. Tree structure not covered in current data.",
    );
  if (!hasInactive)
    console.warn(
      "[e2e] No inactive categories found. Only active categories present in current data.",
    );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate list and hierarchical structure of discussion board categories with
 * deep nesting.
 *
 * This test confirms that the GET /discussionBoard/categories endpoint returns
 * a flat list of all categories, including deeply nested structures, and that
 * parent_id relations are consistently and correctly reflected.
 *
 * Test steps:
 *
 * 1. As admin, create several categories:
 *
 * - At least two root categories (no parent_id)
 * - Multiple child categories with parent_id referencing root categories
 * - One or more third-level (nested) categories, referencing a child as parent
 *
 * 2. Call GET /discussionBoard/categories
 * 3. Validate that:
 *
 * - All created categories are present in the data array
 * - Each child has the correct parent_id
 * - All root categories have parent_id null
 * - All third-level (or deeper) categories have parent_id referencing an
 *   appropriate (existing) second-level category
 * - The returned array is flat (i.e., not a nested data structure)
 *
 * Edge cases: If time permits, test with an inactive category, or categories
 * with missing intermediate parent (should not happen via normal UI but is
 * possible via direct post).
 */
export async function test_api_discussionBoard_test_list_discussion_board_categories_with_many_hierarchies(
  connection: api.IConnection,
) {
  // 1. Create root categories
  const root1 = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph()(3),
        is_active: true,
        parent_id: null,
      },
    },
  );
  typia.assert(root1);

  const root2 = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph()(4),
        is_active: true,
        parent_id: null,
      },
    },
  );
  typia.assert(root2);

  // 2. Create child categories (under root1 and root2)
  const child1 = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph()(5),
        is_active: true,
        parent_id: root1.id,
      },
    },
  );
  typia.assert(child1);

  const child2 = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph()(6),
        is_active: true,
        parent_id: root2.id,
      },
    },
  );
  typia.assert(child2);

  // 3. Create a third-level category (child of child1)
  const grandchild =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.paragraph()(7),
        is_active: true,
        parent_id: child1.id,
      },
    });
  typia.assert(grandchild);

  // 4. Fetch all categories
  const res = await api.functional.discussionBoard.categories.index(connection);
  typia.assert(res);

  // 5. Validate presence and parent-child relationship integrity
  const all = res.data;
  const findById = (id: string) => all.find((cat) => cat.id === id);

  TestValidator.predicate("Root 1 present")(!!findById(root1.id));
  TestValidator.predicate("Root 2 present")(!!findById(root2.id));
  TestValidator.predicate("Child 1 present")(!!findById(child1.id));
  TestValidator.predicate("Child 2 present")(!!findById(child2.id));
  TestValidator.predicate("Grandchild present")(!!findById(grandchild.id));

  TestValidator.equals("Root 1 is top-level")(findById(root1.id)?.parent_id)(
    null,
  );
  TestValidator.equals("Root 2 is top-level")(findById(root2.id)?.parent_id)(
    null,
  );
  TestValidator.equals("Child 1 parent is Root 1")(
    findById(child1.id)?.parent_id,
  )(root1.id);
  TestValidator.equals("Child 2 parent is Root 2")(
    findById(child2.id)?.parent_id,
  )(root2.id);
  TestValidator.equals("Grandchild parent is Child 1")(
    findById(grandchild.id)?.parent_id,
  )(child1.id);
  // 6. Confirm flat array structure (not nested arrays)
  TestValidator.predicate("Flat data array - none are arrays")(
    all.every((cat) => !Array.isArray(cat)),
  );
}

