 * 3. 해당 로그를 DELETE 요청으로 삭제
 * 4. 재삭제 시도시 오류가 발생하는지(실제 hard-delete) 검증
 */
export async function test_api_discussionBoard_admin_activityLogs_test_delete_activity_log_successfully_by_admin(
  connection: api.IConnection,
) {
