import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced notification search and filtering for a member.
 *
 * This test scenario verifies that a member can use the PATCH endpoint to
 * filter and paginate their notifications by different criteria: notification
 * type (e.g., 'mention', 'reply', 'system'), delivery status, and unread
 * status.
 *
 * Steps:
 *
 * 1. Register a new discussion board member for testing.
 * 2. Generate notifications with different notification_type and delivery_status
 *    values for this member (at least one each of: 'mention', 'reply',
 *    'system', and a variety of delivery_status like 'delivered', 'pending',
 *    'failed', and both read_at set and unset).
 * 3. Search with PATCH using different filters:
 *
 *    - By notification_type (e.g., only 'mention'), expect only matching
 *         notifications.
 *    - By delivery_status (e.g., 'delivered'), expect only delivered items.
 *    - By unread (read: false), ensure only unread notifications are returned.
 *    - With pagination parameters (limit=2, page=1), verify pagination meta and data
 *         slice.
 *    - Combination filters (e.g., 'mention' & 'delivered' & unread)
 * 4. Assert that the notifications in each response match the filters and the
 *    pagination meta is correct.
 */
export async function test_api_discussionBoard_member_notifications_test_search_notifications_by_type_and_read_status(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member via admin API
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: `testuser_${typia.random<string>()}`,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create various notifications for this member
  const notifications = [
    // delivered, unread, mention
    {
      notification_type: "mention",
      delivery_status: "delivered",
      read: false,
    },
    // delivered, read, reply
    { notification_type: "reply", delivery_status: "delivered", read: true },
    // pending, unread, system
    { notification_type: "system", delivery_status: "pending", read: false },
    // failed, unread, reply
    { notification_type: "reply", delivery_status: "failed", read: false },
  ];
  const created_ids: string[] = [];
  for (const config of notifications) {
    const notif =
      await api.functional.discussionBoard.admin.notifications.create(
        connection,
        {
          body: {
            recipient_id: member.id,
            notification_type: config.notification_type,
            target_type: "thread",
            target_id: typia.random<string & tags.Format<"uuid">>(),
            message: `${config.notification_type} notification`,
            delivered_at: new Date().toISOString(),
            delivery_status: config.delivery_status,
            failure_reason:
              config.delivery_status === "failed" ? "Network error" : null,
          } satisfies IDiscussionBoardNotification.ICreate,
        },
      );
    typia.assert(notif);
    // Mark as read if needed (simulate by setting read_at after creation, if possible in system API)
    // For this test, since we cannot set read_at directly on creation,
    // we simply test patches for unread (read_at: undefined).
    created_ids.push(notif.id);
  }

  // 3. Test advanced filtering with PATCH
  // a. Filter by notification_type = 'mention'
  const outMention =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      {
        body: {
          notification_type: "mention",
          recipient_id: member.id,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(outMention);
  TestValidator.predicate("only mention notifications")(
    outMention.data.every((n) => n.notification_type === "mention"),
  );

  // b. Filter by delivery_status = 'delivered'
  const outDelivered =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      {
        body: {
          delivery_status: "delivered",
          recipient_id: member.id,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(outDelivered);
  TestValidator.predicate("only delivered")(
    outDelivered.data.every((n) => n.delivery_status === "delivered"),
  );

  // c. Filter unread (read: false)
  const outUnread =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      {
        body: {
          read: false,
          recipient_id: member.id,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(outUnread);
  TestValidator.predicate("only unread")(
    outUnread.data.every((n) => !n.read_at),
  );

  // d. Pagination (limit 2)
  const outPaged =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      {
        body: {
          recipient_id: member.id,
          limit: 2,
          page: 1,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(outPaged);
  TestValidator.equals("limit")(outPaged.pagination.limit)(2);
  TestValidator.equals("current page")(outPaged.pagination.current)(1);
  TestValidator.equals("records")(outPaged.pagination.records)(
    notifications.length,
  );
  TestValidator.equals("pages")(outPaged.pagination.pages)(
    Math.ceil(notifications.length / 2),
  );

  // e. Combined filter: notification_type = mention, delivery_status = delivered, unread
  const outCombined =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      {
        body: {
          recipient_id: member.id,
          notification_type: "mention",
          delivery_status: "delivered",
          read: false,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(outCombined);
  TestValidator.predicate("all combined filters")(
    outCombined.data.every(
      (n) =>
        n.notification_type === "mention" &&
        n.delivery_status === "delivered" &&
        !n.read_at,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템/카테고리별 공지사항 목록을 모더레이터 권한으로 모두 조회(상태 제한 없이) 검증하는 테스트.
 *
 * - 활성, 비활성(숨김), 미래 예약(스케줄), 기간 만료 등 시스템 공지사항을 각각 생성
 * - 모더레이터 권한으로 목록 전체를 조회하고, 직접 생성한 각 상태별 공지사항이 모두 반환되는지 확인
 * - 반환된 각 데이터에 category_id, title, body, is_active, start_at, end_at, created_at,
 *   updated_at 필드가 모두 포함되어 있는지 검증
 * - Pagination 정보(current, limit, records, pages)가 올바른지 확인
 *
 * Step by Step:
 *
 * 1. 관리자 권한으로 활성, 비활성, 예약, 만료 상태 시스템 공지사항 각각 생성
 * 2. 모더레이터 권한으로 시스템 공지사항 전체 목록을 조회
 * 3. 반환 데이터에서 1에서 만든 4개 ID가 모두 포함되는지 확인
 * 4. 각 공지에 모든 필수 메타 필드가 포함되어 있는지 체크(category_id, title, body, is_active, start_at,
 *    end_at, created_at, updated_at)
 * 5. Pagination 메타정보의 각 필드(current, limit, records, pages) 존재·타입·값 검증
 */
export async function test_api_discussionBoard_test_list_system_notices_as_moderator_with_access_to_all_visibility_statuses(
  connection: api.IConnection,
) {
  // 1. 다양한 상태의 공지사항을 관리자 권한에서 직접 생성
  const now = new Date();
  const inOneWeek = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // +7일
  const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000); // -7일

  // 활성(공개)
  const noticeActive =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[ACTIVE] 활성 공지",
          body: "이 공지는 즉시 활성화됨",
          is_active: true,
          start_at: null,
          end_at: null,
          category_id: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeActive);

  // 비활성(숨김)
  const noticeInactive =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[INACTIVE] 숨김 공지",
          body: "이 공지는 비활성 처리됨",
          is_active: false,
          start_at: null,
          end_at: null,
          category_id: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeInactive);

  // 예약(미래 노출 예정)
  const noticeScheduled =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[SCHEDULED] 예약 공지",
          body: "이 공지는 미래에 노출 예정",
          is_active: true,
          start_at: inOneWeek.toISOString(),
          end_at: null,
          category_id: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeScheduled);

  // 만료(과거 노출)
  const noticeExpired =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[EXPIRED] 만료 공지",
          body: "이 공지는 과거에 노출되었고 현재 만료됨",
          is_active: true,
          start_at: oneWeekAgo.toISOString(),
          end_at: now.toISOString(),
          category_id: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeExpired);

  // 2. 모더레이터 권한으로 공지 목록 전체 불러오기
  const result =
    await api.functional.discussionBoard.moderator.systemNotices.index(
      connection,
    );
  typia.assert(result);

  // 3. 실제로 생성한 4개 각 notice의 id가 반환 데이터에 모두 존재하는지 확인
  const createdIds = [
    noticeActive.id,
    noticeInactive.id,
    noticeScheduled.id,
    noticeExpired.id,
  ];
  const returnedIds = result.data.map((n) => n.id);
  createdIds.forEach((id) => {
    TestValidator.predicate(`공지 ID(${id}) 포함 여부`)(
      returnedIds.includes(id),
    );
  });

  // 4. 반환 데이터의 메타 필드 체크
  result.data.forEach((notice) => {
    TestValidator.predicate("id 문자열 여부")(
      typeof notice.id === "string" && !!notice.id,
    );
    TestValidator.predicate("title 문자열 여부")(
      typeof notice.title === "string" && !!notice.title,
    );
    TestValidator.predicate("body 문자열 여부")(
      typeof notice.body === "string",
    );
    TestValidator.predicate("is_active 불린 여부")(
      typeof notice.is_active === "boolean",
    );
    TestValidator.predicate("created_at 문자열 여부")(
      typeof notice.created_at === "string",
    );
    TestValidator.predicate("updated_at 문자열 여부")(
      typeof notice.updated_at === "string",
    );
    // option field (nullable)
    TestValidator.predicate("category_id string/null/undefined 허용")(
      typeof notice.category_id === "string" ||
        notice.category_id === null ||
        notice.category_id === undefined,
    );
    TestValidator.predicate("start_at string/null/undefined 허용")(
      typeof notice.start_at === "string" ||
        notice.start_at === null ||
        notice.start_at === undefined,
    );
    TestValidator.predicate("end_at string/null/undefined 허용")(
      typeof notice.end_at === "string" ||
        notice.end_at === null ||
        notice.end_at === undefined,
    );
  });

  // 5. pagination 정보 각 필드 존재/타입 검증
  TestValidator.predicate("pagination.current number")(
    typeof result.pagination.current === "number",
  );
  TestValidator.predicate("pagination.limit number")(
    typeof result.pagination.limit === "number",
  );
  TestValidator.predicate("pagination.records number")(
    typeof result.pagination.records === "number",
  );
  TestValidator.predicate("pagination.pages number")(
    typeof result.pagination.pages === "number",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Validate category-based filtering and pagination for system notice listing
 * (moderator API).
 *
 * Business context: The discussion board supports system notices that may be
 * global (not category-limited) or assigned to a specific category. Moderators
 * need to see both global and category-specific notices, and UI/UX needs to
 * confirm list/pagination and filtering work.
 *
 * Steps:
 *
 * 1. Admin creates a board category.
 * 2. Admin creates a system notice linked to that category (category-specific
 *    notice).
 * 3. Admin creates several global notices (category_id null).
 * 4. (Optional) Admin creates additional notices to ensure there are enough to
 *    test pagination (limit/page behavior).
 * 5. Moderator calls GET /discussionBoard/moderator/systemNotices to list notices
 *    (covering both unfiltered and filtered scenarios if query params
 *    supported).
 * 6. Verify response contains both the category-specific and global notices (at
 *    minimum). Ensure notices have expected fields and correct category
 *    linkage.
 * 7. If pagination is triggered, confirm paging info (total records, limit, pages,
 *    correct number of results). As API doesn't accept paging query params,
 *    this only confirms 1st page info.
 */
export async function test_api_discussionBoard_test_list_system_notices_pagination_and_filtering_by_category_id(
  connection: api.IConnection,
) {
  // 1. Admin creates a board category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: `Category_${RandomGenerator.alphaNumeric(6)}`,
        description: RandomGenerator.paragraph()(),
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 2. Create a category-specific notice
  const noticeByCategory =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: category.id,
          title: `Cat-Notice_${RandomGenerator.alphaNumeric(5)}`,
          body: RandomGenerator.paragraph()(),
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeByCategory);

  // 3. Create multiple global notices (category_id null)
  const globalNotices: IDiscussionBoardSystemNotice[] = [];
  for (let i = 0; i < 7; ++i) {
    // Create enough notices to test pagination (assuming default limit is sufficiently small)
    const notice =
      await api.functional.discussionBoard.admin.systemNotices.create(
        connection,
        {
          body: {
            category_id: null,
            title: `GlobalNotice_${i}_${RandomGenerator.alphaNumeric(4)}`,
            body: RandomGenerator.paragraph()(),
            is_active: true,
          } satisfies IDiscussionBoardSystemNotice.ICreate,
        },
      );
    typia.assert(notice);
    globalNotices.push(notice);
  }

  // 4. Moderator requests the notice list
  const response =
    await api.functional.discussionBoard.moderator.systemNotices.index(
      connection,
    );
  typia.assert(response);

  // 5. Validate that both global and category-specific notices are found
  // -- Contains category-specific notice
  TestValidator.predicate("category-specific notice included")(
    response.data.some(
      (n) => n.id === noticeByCategory.id && n.category_id === category.id,
    ),
  );
  // -- Contains all created global notices
  for (const notice of globalNotices) {
    TestValidator.predicate(`global notice ${notice.title} included`)(
      response.data.some((n) => n.id === notice.id && n.category_id === null),
    );
  }

  // -- Specific validation on linkage fields
  TestValidator.equals("category_id linkage")(noticeByCategory.category_id)(
    category.id,
  );
  for (const notice of globalNotices) {
    TestValidator.equals("global notice has null category_id")(
      notice.category_id,
    )(null);
  }

  // 6. Check paging information (on 1st result page, as query-args not supported)
  TestValidator.predicate("records count >= created")(
    response.pagination.records >= 1 + globalNotices.length,
  );
  TestValidator.predicate("page size <= limit")(
    response.data.length <= response.pagination.limit,
  );
  TestValidator.predicate("page count > 0")(response.pagination.pages > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 검증: 비로그인(게스트) 사용자는 시스템 공지 중에서 활성 상태이면서 현재 노출 스케줄(시간)에 해당하는 공지만 조회할 수 있다.
 *
 * [비즈니스 배경 및 목적]
 *
 * - 게스트(미인증 사용자)는 discussionBoard 시스템 공지 목록을 요청 시, 반드시 현재 활성화(is_active=true) 및
 *   현재 start_at/end_at 스케줄 내에 있는 공지만 볼 수 있어야 하며, 비활성/만료/예정 공지나 숨김 공지는 절대 반환되어서는
 *   안된다.
 *
 * [테스트 시나리오]
 *
 * 1. 관리자가 아래와 같은 다양한 상태의 시스템 공지를 생성한다.
 *
 *    - 활성(항상 노출, 일정 없음)
 *    - 활성(현재 스케줄 내)
 *    - 활성(스케줄이 미래 시작)
 *    - 활성(스케줄이 이미 종료)
 *    - 비활성(상시)
 * 2. 인증 없이 (게스트) GET /discussionBoard/moderator/systemNotices 호출
 * 3. 응답 데이터에 대해 다음을 검증한다.
 *
 *    - 활성 & 현재 노출 대상만 포함
 *    - 미래 스케줄, 만료, 비활성은 미노출
 *    - 노출되는 객체의 타이틀/본문 등 내용 정확 매칭
 */
export async function test_api_discussionBoard_test_list_system_notices_for_guest_visibility_scope(
  connection: api.IConnection,
) {
  // 1. 기준 시간(now) 정의 (스케줄 판별용)
  const now = new Date();

  // 2. 각 시나리오별 시스템 공지 등록
  // 2-1. 활성/항상 노출 (스케줄 없음)
  const notice_active_always =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Active, always visible",
          body: "This notice should always be shown while active.",
          is_active: true,
          category_id: null,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(notice_active_always);

  // 2-2. 활성/현재 노출 (현재시간 포함한 유효 스케줄)
  const notice_active_current =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Active, currently scheduled",
          body: "Visible to guests: start_at <= now <= end_at.",
          is_active: true,
          category_id: null,
          start_at: new Date(now.getTime() - 60 * 1000).toISOString(), // 1분 전 시작
          end_at: new Date(now.getTime() + 3600 * 1000).toISOString(), // 1시간 후 종료
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(notice_active_current);

  // 2-3. 활성/미래 예정 (아직 노출 X)
  const notice_active_future =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Active, scheduled for future",
          body: "Should NOT be visible to guests yet.",
          is_active: true,
          category_id: null,
          start_at: new Date(now.getTime() + 86400 * 1000).toISOString(), // 1일 후 시작
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(notice_active_future);

  // 2-4. 활성/만료 (이미 끝남)
  const notice_active_expired =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Active, expired",
          body: "Was once visible, but now expired.",
          is_active: true,
          category_id: null,
          start_at: new Date(now.getTime() - 86400 * 1000).toISOString(), // 1일 전 시작
          end_at: new Date(now.getTime() - 60 * 1000).toISOString(), // 1분 전 종료
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(notice_active_expired);

  // 2-5. 비활성/상시
  const notice_inactive =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Inactive, always",
          body: "Inactive notices must never be visible to guests.",
          is_active: false,
          category_id: null,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(notice_inactive);

  // 3. 게스트(비로그인)로 공지 목록 조회 (GET)
  const output =
    await api.functional.discussionBoard.moderator.systemNotices.index(
      connection,
    );
  typia.assert(output);

  // 4-1. 노출되어야 할 공지 ID 목록
  const ids_should_be_visible = [
    notice_active_always.id,
    notice_active_current.id,
  ];
  // 4-2. 실제 응답 ID 리스트
  const visible_ids = output.data.map((n) => n.id);

  // 4-3. 반환 결과에 반드시 포함되어야 하는 공지들
  for (const expected_id of ids_should_be_visible) {
    TestValidator.predicate(`notice ${expected_id} must be visible as guest`)(
      visible_ids.includes(expected_id),
    );
  }
  // 4-4. 반대로, 절대 포함되면 안 되는 공지들 (미래/만료/숨김)
  for (const not_expected of [
    notice_active_future.id,
    notice_active_expired.id,
    notice_inactive.id,
  ]) {
    TestValidator.predicate(
      `notice ${not_expected} must NOT be visible as guest`,
    )(!visible_ids.includes(not_expected));
  }

  // 5. 타이틀/본문 등의 정확성 추가 검증
  const by_id = Object.fromEntries(output.data.map((n) => [n.id, n]));
  TestValidator.equals("title matches")(by_id[notice_active_always.id]?.title)(
    "Active, always visible",
  );
  TestValidator.equals("body matches")(by_id[notice_active_always.id]?.body)(
    "This notice should always be shown while active.",
  );

  TestValidator.equals("title matches")(by_id[notice_active_current.id]?.title)(
    "Active, currently scheduled",
  );
  TestValidator.equals("body matches")(by_id[notice_active_current.id]?.body)(
    "Visible to guests: start_at <= now <= end_at.",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 시스템 공지사항 고급 검색 기능 검증
 *
 * 이 테스트는 관리자가 고급 검색 필터(활성/비활성 상태, 스케줄 window의 start_at/end_at, 제목 또는 본문 텍스트
 * 매칭)를 통해 시스템 공지사항을 정확히 조회할 수 있음을 검증한다.
 *
 * 1. 다양한 조합(상시 활성, 특정 기간 활성, 비활성, 미래 예정 등)과 서로 다른 제목/본문 텍스트, 시작/종료 시간 값으로 System
 *    Notice 데이터를 최소 4개 이상 생성해둔다.
 * 2. 각각의 필터 조건별로 PATCH "search" 요청을 시도한다. (is_active, start_at_from/to,
 *    end_at_from/to, title, body 등)
 * 3. 각각의 검색 결과에 대해 반환된 공지사항 목록이 요청 조건을 충족하는지(데이터 필터 조건에 딱 맞게 조회되는지), 페이징 결과(페이지/개수
 *    등) 및 빈 검색 결과도 적절히 반환되는지 확인한다.
 *
 * - 활성화 상태가 true인 것만 필터
 * - 비활성(활성화 상태 false) 필터
 * - 특정 기간에 노출되는 공지만 start_at, end_at 기준으로 필터
 * - 텍스트(제목/본문) 포함 검색
 * - 일치하는 공지가 없는 케이스도 체크(빈 배열 반환)
 */
export async function test_api_discussionBoard_admin_systemNotices_test_advanced_search_of_system_notices_by_status_and_date(
  connection: api.IConnection,
) {
  // ==== 유틸리티: 미래/과거 시간 생성 ====
  function getDate(offsetMinutes: number): string {
    return new Date(Date.now() + offsetMinutes * 60_000).toISOString();
  }
  // ==== 1. 테스트 데이터 생성: 다양한 조합의 system notice 등록 ====
  /** 각 공지가 고유하게 식별될 수 있도록 title/body 고유 키/타임스탬프 조합 사용 시간 분산(과거, 현재, 미래) */
  const now = Date.now();
  // 상시 활성화(언제나 노출, 텍스트: "NOTICE_PERMANENT").
  const noticePermanent =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: `NOTICE_PERMANENT_${now}`,
          body: `본문:PERMANENT_${now}`,
          is_active: true,
          start_at: null,
          end_at: null,
          category_id: null,
        },
      },
    );
  typia.assert(noticePermanent);

  // 특정 기간 활성화(현재~20분 후), 텍스트: "NOTICE_TIMEWINDOW"
  const noticeTimeWindow =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: `NOTICE_TIMEWINDOW_${now}`,
          body: `본문:TIMEWINDOW_${now}`,
          is_active: true,
          start_at: getDate(0),
          end_at: getDate(20),
          category_id: null,
        },
      },
    );
  typia.assert(noticeTimeWindow);

  // 비활성, 특정 기간(과거~미래), 텍스트: "NOTICE_INACTIVE"
  const noticeInactive =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: `NOTICE_INACTIVE_${now}`,
          body: `본문:INACTIVE_${now}`,
          is_active: false,
          start_at: getDate(-10),
          end_at: getDate(10),
          category_id: null,
        },
      },
    );
  typia.assert(noticeInactive);

  // 미래 시작 예정(5분뒤~30분뒤), 텍스트: "NOTICE_FUTURE"
  const noticeFuture =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: `NOTICE_FUTURE_${now}`,
          body: `본문:FUTURE_${now}`,
          is_active: true,
          start_at: getDate(5),
          end_at: getDate(30),
          category_id: null,
        },
      },
    );
  typia.assert(noticeFuture);

  // ==== 2. status별(is_active) 검색 ====
  // 활성화 공지 (is_active: true)
  {
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            is_active: true,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("활성화 필터: 모두 is_active true인지")(
      output.data.every((n) => n.is_active === true),
    );
  }
  // 비활성화 공지 (is_active: false)
  {
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            is_active: false,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("비활성화 필터: 모두 is_active false인지")(
      output.data.every((n) => n.is_active === false),
    );
  }

  // ==== 3. 기간별 검색 ====
  // start_at로만 필터 (start_at_from: now)
  {
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            start_at_from: getDate(0),
          },
        },
      );
    typia.assert(output);
    // noticeTimeWindow, noticeFuture가 포함되어야 함
    const ids = output.data.map((n) => n.id);
    TestValidator.predicate(
      "start_at_from 검색: noticeTimeWindow, noticeFuture 포함",
    )(ids.includes(noticeTimeWindow.id) && ids.includes(noticeFuture.id));
  }
  // end_at로만 필터 (end_at_to: now+15분)
  {
    const endLimit = getDate(15);
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            end_at_to: endLimit,
          },
        },
      );
    typia.assert(output);
    // noticeTimeWindow, noticeInactive만 포함되는지
    const ids = output.data.map((n) => n.id);
    TestValidator.predicate(
      "end_at_to 검색: noticeTimeWindow, noticeInactive 포함",
    )(ids.includes(noticeTimeWindow.id) && ids.includes(noticeInactive.id));
  }

  // ==== 4. 텍스트(제목/본문) 부분 일치 검색 ====
  // title 포함 검색
  {
    const keyword = `PERMANENT_${now}`;
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            title: keyword,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("title 검색: PERMANENT 키워드 포함")(
      output.data.some((n) => n.title.includes(keyword)),
    );
  }
  // body 포함 검색
  {
    const keyword = `본문:INACTIVE_${now}`;
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            body: keyword,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("body 검색: 본문 INACTIVE 키워드 포함")(
      output.data.some((n) => n.body.includes(keyword)),
    );
  }

  // ==== 5. 일치하는 공지가 없는 케이스 (빈 배열 반환) ====
  {
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            title: `NO_MATCH_${now}`,
          },
        },
      );
    typia.assert(output);
    TestValidator.equals("검색 결과 없음(empty)")(output.data)([]);
  }

  // ==== 6. 페이징 기본 검증 ====
  {
    const output =
      await api.functional.discussionBoard.admin.systemNotices.search(
        connection,
        {
          body: {
            limit: 2,
            page: 1,
          },
        },
      );
    typia.assert(output);
    TestValidator.equals("limit=2일 때 한 페이지 최대 2개")(
      output.data.length <= 2,
    )(true);
    TestValidator.equals("pagination.limit=2")(output.pagination.limit)(2);
    TestValidator.equals("pagination.current=1")(output.pagination.current)(1);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced system notice search by moderators with text and category
 * filters.
 *
 * This test verifies that moderators can:
 *
 * - Search system notices by title and body keywords (fulltext search)
 * - Filter notices by a specific category
 *
 * The test creates:
 *
 * - Two categories (catA and catB)
 * - 4 system notices: (a) Global, title="Welcome", body="This is a system-wide
 *   update." (b) Category A only, title="CatA Issue", body="Notice for category
 *   A." (c) Category B only, title="CatB Maint", body="Maintenance for B." (d)
 *   Category A only, title="Update", body="CatA big changes."
 *
 * Test steps:
 *
 * 1. Create categories catA and catB
 * 2. Create system notices as above (some with category_id=null for global)
 * 3. Moderator searches for notices with title contains "cat" (should match b & c)
 * 4. Search by category_id = catA.id (should yield notices b & d)
 * 5. Search by title contains "update" AND category_id = catA.id (should yield
 *    only d)
 * 6. Search by a non-existent keyword (should return zero notices)
 * 7. Validate all filtering is correct and returns only matching items.
 */
export async function test_api_discussionBoard_test_moderator_advanced_search_of_system_notices_by_text_and_category(
  connection: api.IConnection,
) {
  // 1. Create two categories: catA and catB
  const catA = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: "CategoryA",
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(catA);

  const catB = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: "CategoryB",
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(catB);

  // 2. Create 4 notices (global and per category)
  // a) Global
  const noticeGlobal =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: null,
          title: "Welcome",
          body: "This is a system-wide update.",
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeGlobal);

  // b) catA
  const noticeCatA =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: catA.id,
          title: "CatA Issue",
          body: "Notice for category A.",
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeCatA);

  // c) catB
  const noticeCatB =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: catB.id,
          title: "CatB Maint",
          body: "Maintenance for B.",
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeCatB);

  // d) catA, another
  const noticeA2 =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: catA.id,
          title: "Update",
          body: "CatA big changes.",
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(noticeA2);

  // 3. Search: title contains "cat" (case-insensitive)
  const searchCat =
    await api.functional.discussionBoard.moderator.systemNotices.search(
      connection,
      {
        body: { title: "cat" } satisfies IDiscussionBoardSystemNotice.IRequest,
      },
    );
  typia.assert(searchCat);
  TestValidator.predicate("title keyword: only cat-related")(
    searchCat.data.every((n) => /cat/i.test(n.title)),
  );

  // 4. Search by category_id: catA
  const searchCatA =
    await api.functional.discussionBoard.moderator.systemNotices.search(
      connection,
      {
        body: {
          category_id: catA.id,
        } satisfies IDiscussionBoardSystemNotice.IRequest,
      },
    );
  typia.assert(searchCatA);
  TestValidator.predicate("categoryA filter")(
    searchCatA.data.every((n) => n.category_id === catA.id),
  );

  // 5. Search by title contains "update" AND category_id = catA.id
  const searchUpdateA =
    await api.functional.discussionBoard.moderator.systemNotices.search(
      connection,
      {
        body: {
          title: "update",
          category_id: catA.id,
        } satisfies IDiscussionBoardSystemNotice.IRequest,
      },
    );
  typia.assert(searchUpdateA);
  TestValidator.equals("single match for update + catA")(
    searchUpdateA.data.length,
  )(1);
  TestValidator.equals("correct notice for update + catA")(
    searchUpdateA.data[0].id,
  )(noticeA2.id);

  // 6. Negative: Search by a non-existent keyword
  const searchNegative =
    await api.functional.discussionBoard.moderator.systemNotices.search(
      connection,
      {
        body: {
          title: "nonexistentkeyword",
        } satisfies IDiscussionBoardSystemNotice.IRequest,
      },
    );
  typia.assert(searchNegative);
  TestValidator.equals("empty for nonexistent keyword")(
    searchNegative.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 관리자(Admin)가 다양한 상태(활성, 비활성, 만료, 예약)인 시스템 공지사항들의 상세정보를 정상적으로 조회할 수 있는지 검증합니다.
 *
 * - 각 상태(활성, 비활성, 종료, 예약)별 공지사항을 생성합니다.
 * - 생성된 각각의 공지사항을 상세조회(GET) API로 조회하여, 모든 필드(카테고리 연결, 스케줄링, 활성상태, 생성/수정시각 등)가 정확히
 *   조회되는지 검사합니다.
 *
 *   - 생성 입력값과 조회 결과가 완벽히 일치해야 함
 * - 존재하지 않는 임의의 UUID로 조회시 404 응답을 반환하는지를 검사합니다.
 *
 * [테스트 순서]
 *
 * 1. 활성화된 공지사항 생성 (is_active: true, start_at: 과거, end_at: 미래)
 * 2. 비활성화된 공지사항 생성 (is_active: false, start_at: null, end_at: null)
 * 3. 만료된 공지사항 생성 (is_active: true, start_at: 과거, end_at: 과거)
 * 4. 예약(미래) 공지사항 생성 (is_active: true, start_at: 미래, end_at: 더 미래)
 * 5. 각 공지사항에 대해 admin 조회 API 호출 후 조회정보를 생성내용과 비교(카테고리 연결, 스케줄, 상태 등 포함)
 * 6. 존재하지 않는 UUID로 조회 시도 → 404 오류 확인
 */
export async function test_api_discussionBoard_admin_systemNotices_at_test_fetch_system_notice_detail_as_admin_various_statuses(
  connection: api.IConnection,
) {
  // 1. 활성화된 공지사항 생성 (is_active: true, start_at: 과거, end_at: 미래)
  const now = new Date();
  const past = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(); // 일주일 전
  const future = new Date(
    now.getTime() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 일주일 후

  const activeNoticeInput = {
    category_id: null,
    title: "활성 공지",
    body: "활성화된 시스템 공지입니다.",
    is_active: true,
    start_at: past,
    end_at: future,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const activeNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: activeNoticeInput },
    );
  typia.assert(activeNotice);

  // 2. 비활성화된 공지사항 생성 (is_active: false, start_at/end_at null)
  const inactiveNoticeInput = {
    category_id: null,
    title: "비활성 공지",
    body: "비활성화된 시스템 공지입니다.",
    is_active: false,
    start_at: null,
    end_at: null,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const inactiveNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: inactiveNoticeInput },
    );
  typia.assert(inactiveNotice);

  // 3. 만료된 공지사항 생성 (is_active: true, start_at: 과거, end_at: 과거)
  const expiredEnd = new Date(
    now.getTime() - 1 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 하루 전
  const expiredNoticeInput = {
    category_id: null,
    title: "만료 공지",
    body: "만료된 시스템 공지입니다.",
    is_active: true,
    start_at: past,
    end_at: expiredEnd,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const expiredNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: expiredNoticeInput },
    );
  typia.assert(expiredNotice);

  // 4. 예약(미래) 공지사항 생성 (is_active: true, start_at: 미래, end_at: 더 미래)
  const scheduledStart = new Date(
    now.getTime() + 2 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 2일 후
  const scheduledEnd = new Date(
    now.getTime() + 9 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 9일 후
  const scheduledNoticeInput = {
    category_id: null,
    title: "예약 공지",
    body: "예약(미래) 시스템 공지입니다.",
    is_active: true,
    start_at: scheduledStart,
    end_at: scheduledEnd,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const scheduledNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: scheduledNoticeInput },
    );
  typia.assert(scheduledNotice);

  // 5. 각 공지사항 상세 조회 후 생성 시점/입력값과 비교
  const notices = [
    { input: activeNoticeInput, created: activeNotice },
    { input: inactiveNoticeInput, created: inactiveNotice },
    { input: expiredNoticeInput, created: expiredNotice },
    { input: scheduledNoticeInput, created: scheduledNotice },
  ];
  for (const { input, created } of notices) {
    const detail = await api.functional.discussionBoard.admin.systemNotices.at(
      connection,
      { systemNoticeId: created.id },
    );
    typia.assert(detail);
    // 필드 일치 여부 검사
    TestValidator.equals("category_id")(detail.category_id)(input.category_id);
    TestValidator.equals("title")(detail.title)(input.title);
    TestValidator.equals("body")(detail.body)(input.body);
    TestValidator.equals("is_active")(detail.is_active)(input.is_active);
    TestValidator.equals("start_at")(detail.start_at)(input.start_at);
    TestValidator.equals("end_at")(detail.end_at)(input.end_at);
    // 생성/수정 일시는 존재해야 함
    TestValidator.predicate("created_at 존재")(!!detail.created_at);
    TestValidator.predicate("updated_at 존재")(!!detail.updated_at);
    // ID, created/updated 일시 ISO8601 형식 검증 등은 typia.assert로 충분 (별도 assert 불필요)
  }
  // 6. 존재하지 않는 UUID로 조회 시도 → 404 에러
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 systemNoticeId 요청 시 404")(
    async () => {
      await api.functional.discussionBoard.admin.systemNotices.at(connection, {
        systemNoticeId: nonExistId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템 공지사항의 상세 조회 - moderator 권한의 범위 테스트
 *
 * Moderator가 비공개(숨김, 예정, 만료 포함) 및 공개 상태의 시스템 공지 상세를 모두 조회할 수 있음을 검증합니다. 각 상태별
 * 공지를 생성하고, moderator GET API로 개별 공지의 상세 정보를 조회하여 모든 속성이 일치함을 확인합니다. 또한, 존재하지
 * 않는 공지 ID 조회 시 404 에러가 발생함을 검증합니다.
 *
 * 절차:
 *
 * 1. 현재 활성화(진행 중)인 공지 생성 (is_active: true, 현재 포함한 시작/종료)
 * 2. 비활성/숨김 공지 생성 (is_active: false)
 * 3. 예약(미공개) 공지 생성 (is_active: true, start_at 만 미래)
 * 4. 만료 공지 생성 (is_active: true, start-at/end_at 모두 과거)
 * 5. 위 4개 각각을 moderator endpoint로 조회하여 모든 속성 일치 여부를 검증
 * 6. 존재하지 않는 무작위 UUID로 조회 시 404 에러 발생 확인
 */
export async function test_api_discussionBoard_moderator_systemNotices_test_moderator_fetch_detail_for_inactive_and_scheduled_system_notice(
  connection: api.IConnection,
) {
  // 1. 현재 활성 공지 생성 (now -1h ~ now +1h)
  const now = new Date();
  const past = new Date(now.getTime() - 3600 * 1000).toISOString();
  const future = new Date(now.getTime() + 3600 * 1000).toISOString();

  const activeNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[E2E] 활성 공지",
          body: "현재 공개 중인 시스템 공지입니다.",
          is_active: true,
          category_id: null,
          start_at: past,
          end_at: future,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(activeNotice);

  // 2. 비활성(숨김) 공지 생성
  const inactiveNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[E2E] 숨김 공지",
          body: "비공개(숨김) 시스템 공지입니다.",
          is_active: false,
          category_id: null,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(inactiveNotice);

  // 3. 예약(미공개) 공지 생성 (start_at 미래)
  const scheduledNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[E2E] 예정 공지",
          body: "곧 오픈될(예정) 시스템 공지입니다.",
          is_active: true,
          category_id: null,
          start_at: future,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(scheduledNotice);

  // 4. 만료 공지 생성 (start_at/end_at 모두 과거)
  const expiredStart = new Date(now.getTime() - 7200 * 1000).toISOString();
  const expiredEnd = new Date(now.getTime() - 3600 * 1000).toISOString();
  const expiredNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "[E2E] 만료 공지",
          body: "기한이 지난(만료) 시스템 공지입니다.",
          is_active: true,
          category_id: null,
          start_at: expiredStart,
          end_at: expiredEnd,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(expiredNotice);

  // 5. 각 공지 상세조회 (moderator 권한 API)
  for (const notice of [
    activeNotice,
    inactiveNotice,
    scheduledNotice,
    expiredNotice,
  ]) {
    const fetched =
      await api.functional.discussionBoard.moderator.systemNotices.at(
        connection,
        {
          systemNoticeId: notice.id,
        },
      );
    typia.assert(fetched);
    TestValidator.equals("공지 상세 속성 일치")(fetched)({ ...notice });
  }

  // 6. 존재하지 않는 ID 조회 오류 검사
  TestValidator.error("존재하지 않는 공지 404 반환")(async () => {
    await api.functional.discussionBoard.moderator.systemNotices.at(
      connection,
      {
        systemNoticeId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Validate that an admin can retrieve all attachments for a comment authored by
 * a member.
 *
 * This test ensures:
 *
 * - Admin creates a new member
 * - Member creates a comment under a post
 * - Admin attaches files to that comment
 * - Admin lists all attachments and verifies all files, with correct metadata
 *
 * Steps:
 *
 * 1. As admin, create a new IDiscussionBoardMember (member)
 * 2. Create a valid postId (simulate as random UUID for test context)
 * 3. As member, create a comment attached to the postId
 *    (discussion_board_member_id is member.id)
 * 4. As admin, attach two files to the created comment
 * 5. As admin, retrieve all attachments for that comment
 * 6. Validate all attached files are present, with correct fields
 */
export async function test_api_discussionBoard_test_list_comment_attachments_admin_valid_member_comment(
  connection: api.IConnection,
) {
  // 1. Admin creates a member
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: RandomGenerator.alphaNumeric(12),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a test post ID (simulate with random UUID)
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 3. Member creates a comment under the post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: member.id,
        discussion_board_post_id: postId,
        content: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 4. Admin attaches two files to the comment
  const attachments = await Promise.all([
    api.functional.discussionBoard.admin.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          uploader_member_id: member.id,
          file_name: "file1.txt",
          file_url: "https://cdn.example.com/file1.txt",
          mime_type: "text/plain",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    ),
    api.functional.discussionBoard.admin.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          uploader_member_id: member.id,
          file_name: "file2.png",
          file_url: "https://cdn.example.com/file2.png",
          mime_type: "image/png",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    ),
  ]);
  attachments.forEach((a) => typia.assert(a));

  // 5. Admin retrieves list of attachments for that comment
  const listed =
    await api.functional.discussionBoard.admin.comments.attachments.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(listed);

  // 6. Validate the response contains both attachments and metadata matches
  TestValidator.equals("attachment count matches")(listed.data.length)(
    attachments.length,
  );
  const byName = Object.fromEntries(listed.data.map((a) => [a.file_name, a]));
  for (const [i, input] of [
    {
      file_name: "file1.txt",
      mime_type: "text/plain",
      file_url: "https://cdn.example.com/file1.txt",
    },
    {
      file_name: "file2.png",
      mime_type: "image/png",
      file_url: "https://cdn.example.com/file2.png",
    },
  ].entries()) {
    const found = byName[input.file_name];
    TestValidator.predicate(`attachment #${i + 1} present`)(!!found);
    if (found) {
      TestValidator.equals(`file_name #${i + 1}`)(found.file_name)(
        input.file_name,
      );
      TestValidator.equals(`mime_type #${i + 1}`)(found.mime_type)(
        input.mime_type,
      );
      TestValidator.equals(`file_url #${i + 1}`)(found.file_url)(
        input.file_url,
      );
      TestValidator.equals(`uploader_member_id #${i + 1}`)(
        found.uploader_member_id,
      )(member.id);
      TestValidator.equals(`discussion_board_comment_id #${i + 1}`)(
        found.discussion_board_comment_id,
      )(comment.id);
      TestValidator.predicate(`uploaded_at #${i + 1} is date-time`)(
        !isNaN(Date.parse(found.uploaded_at)),
      );
    }
  }
}

