import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import type { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test a member's ability to filter attachments on their own comment using file
 * name, uploader, and MIME type filters. Also, verify proper pagination.
 *
 * Business context: Verifies that after uploading multiple attachments to their
 * own comment, a member can retrieve subsets using various filters and
 * pagination. Ensures search works for partial & exact file_name match,
 * mime_type, uploader ID, and composite filter. Pagination and empty search
 * behaviors are also validated.
 *
 * Steps:
 *
 * 1. Create a new comment as a member
 * 2. Upload several attachments to that comment with different file names and MIME
 *    types
 * 3. Filter/search: file name (partial/exact), MIME type, uploader_member_id,
 *    composite filters
 * 4. Pagination behavior for result sets
 * 5. Non-matching and "no filter" result correctness
 */
export async function test_api_discussionBoard_test_search_comment_attachments_member_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Create a new comment as a member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: memberId,
        discussion_board_post_id: postId,
        content:
          "Comment for attachment filter test - " +
          RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(comment);

  // 2. Upload several attachments to this comment
  const files = [
    {
      file_name: "fileA.jpg",
      mime_type: "image/jpeg",
      file_url: "https://cdn.example.com/fileA.jpg",
    },
    {
      file_name: "fileB.png",
      mime_type: "image/png",
      file_url: "https://cdn.example.com/fileB.png",
    },
    {
      file_name: "testC.docx",
      mime_type:
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      file_url: "https://cdn.example.com/testC.docx",
    },
    {
      file_name: "reportD.pdf",
      mime_type: "application/pdf",
      file_url: "https://cdn.example.com/reportD.pdf",
    },
  ];
  const attachments: IDiscussionBoardCommentAttachment[] = [];
  for (const f of files) {
    const att =
      await api.functional.discussionBoard.member.comments.attachments.create(
        connection,
        {
          commentId: comment.id,
          body: {
            discussion_board_comment_id: comment.id,
            uploader_member_id: memberId,
            file_name: f.file_name,
            file_url: f.file_url,
            mime_type: f.mime_type,
          },
        },
      );
    typia.assert(att);
    attachments.push(att);
  }

  // 3. Filter: file_name partial match ("file")
  let result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, file_name: "file" },
      },
    );
  typia.assert(result);
  TestValidator.predicate("file_name partial match count")(
    result.data.length === 2,
  );
  TestValidator.equals("partial match items")(
    result.data.map((a) => a.file_name).sort(),
  )(["fileA.jpg", "fileB.png"]);

  // 4. Filter: file_name exact match ("testC.docx")
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, file_name: "testC.docx" },
      },
    );
  typia.assert(result);
  TestValidator.predicate("file_name exact match count")(
    result.data.length === 1,
  );
  TestValidator.equals("file_name")(result.data[0].file_name)("testC.docx");

  // 5. Filter: by mime_type ("application/pdf")
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, mime_type: "application/pdf" },
      },
    );
  typia.assert(result);
  TestValidator.predicate("mime_type match count")(result.data.length === 1);
  TestValidator.equals("mime_type")(result.data[0].mime_type)(
    "application/pdf",
  );

  // 6. Filter: by uploader_member_id
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, uploader_member_id: memberId },
      },
    );
  typia.assert(result);
  TestValidator.predicate("uploader_member_id match count")(
    result.data.length === attachments.length,
  );

  // 7. Composite filter: file_name + mime_type
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
          file_name: "fileA.jpg",
          mime_type: "image/jpeg",
        },
      },
    );
  typia.assert(result);
  TestValidator.predicate("composite filter count")(result.data.length === 1);
  TestValidator.equals("file_name")(result.data[0].file_name)("fileA.jpg");
  TestValidator.equals("mime_type")(result.data[0].mime_type)("image/jpeg");

  // 8. Pagination (limit=2, page=1)
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, page: 1, limit: 2 },
      },
    );
  typia.assert(result);
  TestValidator.equals("pagination length")(result.data.length)(2);
  TestValidator.equals("pagination page")(result.pagination.current)(1);
  TestValidator.equals("pagination limit")(result.pagination.limit)(2);

  // 9. Pagination: page 2
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, page: 2, limit: 2 },
      },
    );
  typia.assert(result);
  TestValidator.equals("pagination page 2")(result.pagination.current)(2);
  TestValidator.equals("pagination length")(result.data.length)(2);

  // 10. Non-matching query (file_name: "notfound.txt")
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, file_name: "notfound.txt" },
      },
    );
  typia.assert(result);
  TestValidator.equals("non-matching")(result.data.length)(0);

  // 11. No filter (all attachments, paginated)
  result =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: { comment_id: comment.id, limit: 10 },
      },
    );
  typia.assert(result);
  TestValidator.equals("all items")(result.data.length)(attachments.length);
  TestValidator.equals("id set")(result.data.map((a) => a.id).sort())(
    attachments.map((a) => a.id).sort(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import type { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the search API for comment attachments with pagination and sorting.
 *
 * Business goal: Validate that a board comment's attachment search endpoint
 * correctly honors pagination limits, default page size, and ordering (desc by
 * upload timestamp).
 *
 * Steps:
 *
 * 1. Create a comment as a member.
 * 2. Upload more attachments than a typical default page size (default limit is
 *    assumed 100).
 * 3. Search for attachments without limit param (should return default first
 *    page/size).
 * 4. Search with explicit smaller limit (e.g., 10), and verify returned data size
 *    and order.
 * 5. Request subsequent pages to verify pagination (page 2, page 11 as last page,
 *    page 12 as beyond bounds).
 * 6. On each step, verify both returned data and pagination meta.
 */
export async function test_api_discussionBoard_test_search_comment_attachments_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create a comment
  const member_id: string = typia.random<string & tags.Format<"uuid">>();
  const post_id: string = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: member_id,
        discussion_board_post_id: post_id,
        content: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(comment);

  // 2. Upload more than the default page size (e.g. 105 attachments)
  const attachment_count = 105;
  const files = ArrayUtil.repeat(attachment_count)((i) => ({
    discussion_board_comment_id: comment.id,
    uploader_member_id: member_id,
    file_name: `file_${i + 1}.txt`,
    file_url: `https://cdn.example.com/file_${i + 1}`,
    mime_type: "text/plain",
  }));
  let uploaded_files: IDiscussionBoardCommentAttachment[] = [];
  for (const file of files) {
    const att =
      await api.functional.discussionBoard.member.comments.attachments.create(
        connection,
        {
          commentId: comment.id,
          body: file,
        },
      );
    uploaded_files.push(att);
  }
  // For expectations, sort by uploaded_at desc
  uploaded_files = [...uploaded_files].sort((a, b) =>
    b.uploaded_at.localeCompare(a.uploaded_at),
  );

  // 3. Search without limit (should use default limit of 100)
  const first_page =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
        },
      },
    );
  typia.assert(first_page);
  TestValidator.equals("default page size")(first_page.data.length)(100);
  TestValidator.equals("page size meta")(first_page.pagination.limit)(100);
  TestValidator.equals("total records")(first_page.pagination.records)(
    attachment_count,
  );
  TestValidator.equals("total pages")(first_page.pagination.pages)(2);
  // Confirm returned objects are the most recently uploaded
  for (let i = 0; i < 100; ++i)
    TestValidator.equals(`attachment order default [${i}]`)(
      first_page.data[i].id,
    )(uploaded_files[i].id);

  // 4. Search with limit = 10
  const limited =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
          limit: 10,
        },
      },
    );
  typia.assert(limited);
  TestValidator.equals("limit 10 result count")(limited.data.length)(10);
  TestValidator.equals("limit meta")(limited.pagination.limit)(10);
  for (let i = 0; i < 10; ++i)
    TestValidator.equals(`attachment order limit [${i}]`)(limited.data[i].id)(
      uploaded_files[i].id,
    );

  // 5. Page 2 of limit 10
  const page_2 =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
          limit: 10,
          page: 2,
        },
      },
    );
  typia.assert(page_2);
  TestValidator.equals("page 2 count")(page_2.data.length)(10);
  for (let i = 0; i < 10; ++i)
    TestValidator.equals(`attachment order page2 [${i}]`)(page_2.data[i].id)(
      uploaded_files[i + 10].id,
    );

  // 6. Last valid page: page 11 of limit 10 (only 5 files)
  const last_page =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
          limit: 10,
          page: 11,
        },
      },
    );
  typia.assert(last_page);
  TestValidator.equals("last page is partial")(last_page.data.length)(5);
  for (let i = 0; i < 5; ++i)
    TestValidator.equals(`attachment order last page [${i}]`)(
      last_page.data[i].id,
    )(uploaded_files[100 + i].id);

  // 7. Excess page: page 12 (should return empty array)
  const beyond =
    await api.functional.discussionBoard.member.comments.attachments.search(
      connection,
      {
        commentId: comment.id,
        body: {
          comment_id: comment.id,
          limit: 10,
          page: 12,
        },
      },
    );
  typia.assert(beyond);
  TestValidator.equals("excess page empty")(beyond.data.length)(0);
}

