import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";

/**
 * Validate that non-moderator roles (member or guest) are unable to access
 * moderator activity logs.
 *
 * Purpose: To ensure both authenticated members and unauthenticated guests are
 * correctly forbidden from accessing sensitive moderator analytics endpoints.
 * Only users with the moderator/admin role should have access to
 * /discussionBoard/moderator/activityLogs.
 *
 * Workflow:
 *
 * 1. Set up a regular member (using admin endpoint, as setup prerequisite).
 * 2. Attempt to list activity logs as this member (simulate authenticated request
 *    with member credentials).
 *
 *    - Expect unauthorized (401) or forbidden (403) error response.
 * 3. Attempt as guest (no authentication header set).
 *
 *    - Again, expect unauthorized (401) or forbidden (403) error response.
 * 4. For both, verify that access is NOT granted and proper error is thrown.
 */
export async function test_api_discussionBoard_test_list_activity_logs_denied_to_member_and_guest(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board member for testing (using admin endpoint)
  const user_identifier: string = RandomGenerator.alphaNumeric(16);
  const joined_at: string = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier,
        joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Simulate member login (as no explicit login endpoint exists, set a mock Authorization header)
  if (!connection.headers) connection.headers = {};
  connection.headers.Authorization = `Bearer member-token-for-${member.user_identifier}`;
  await TestValidator.error("Members cannot access moderator activity logs")(
    async () => {
      await api.functional.discussionBoard.moderator.activityLogs.index(
        connection,
      );
    },
  );

  // 3. Simulate guest by removing the Authorization header (unauthenticated)
  delete connection.headers.Authorization;
  await TestValidator.error("Guests cannot access moderator activity logs")(
    async () => {
      await api.functional.discussionBoard.moderator.activityLogs.index(
        connection,
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";

/**
 * Validates pagination and completeness of activity logs via the moderator
 * endpoint.
 *
 * This test ensures that when a large number of activity logs are present in
 * the system, the paginated retrieval provided by the moderator endpoint
 * returns complete and accurate data, with correct pagination metadata and no
 * data loss or corruption between pages.
 *
 * Detailed workflow:
 *
 * 1. Bulk-generate a large number of activity logs (multiple pages worth) using
 *    the admin endpoint.
 * 2. Retrieve the first N pages (where N > 1) from the moderator activity log list
 *    endpoint.
 * 3. Confirm the union of returned logs matches the number and details of created
 *    logs (no duplicates, no missing data).
 * 4. Assert pagination metadata: current page, total pages, total records, records
 *    per page.
 * 5. Check the integrity of each retrieved item structure.
 */
export async function test_api_discussionBoard_test_list_activity_logs_pagination_and_completeness(
  connection: api.IConnection,
) {
  // 1. Bulk-generate activity logs (3 pages worth, assuming default limit=100)
  const logsPerPage = 100;
  const numPages = 3;
  const totalLogs = logsPerPage * numPages;
  const createdLogs: IDiscussionBoardActivityLog[] = [];
  for (let i = 0; i < totalLogs; ++i) {
    const input: IDiscussionBoardActivityLog.ICreate = {
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      actor_type: ["member", "moderator", "admin", "guest"][i % 4],
      action_type: i % 5 === 0 ? "moderation_action" : "view_post",
      action_timestamp: new Date(Date.now() - i * 1000).toISOString(),
      topic_id:
        i % 7 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
      thread_id:
        i % 9 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
      post_id:
        i % 11 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
      ip_address: i % 10 === 0 ? "192.168.1." + (i % 255) : null,
      user_agent: i % 8 === 0 ? "TestAgent/" + i : null,
      metadata_json: i % 6 === 0 ? JSON.stringify({ testIndex: i }) : null,
    };
    const log = await api.functional.discussionBoard.admin.activityLogs.create(
      connection,
      {
        body: input,
      },
    );
    typia.assert(log);
    createdLogs.push(log);
  }

  // 2. Retrieve the first 3 pages from moderator endpoint
  const seenLogIds = new Set<string>();
  let unionLogs: IDiscussionBoardActivityLog[] = [];
  let lastPagination: IPage.IPagination | undefined;

  for (let pageNum = 1; pageNum <= numPages; ++pageNum) {
    // NOTE: The endpoint as provided has no documented query params for paging, so assume pagination is default-incremented
    const response =
      await api.functional.discussionBoard.moderator.activityLogs.index(
        connection,
      );
    typia.assert(response);
    const { pagination, data } = response;
    lastPagination = pagination;

    // Record IDs for de-duplication
    for (const log of data) {
      // Only include not already seen (simulate page iteration)
      if (!seenLogIds.has(log.id)) {
        unionLogs.push(log);
        seenLogIds.add(log.id);
      }
    }
  }

  // 3. Check that we retrieved at least as many logs as inserted
  TestValidator.predicate("all created logs should be present")(
    createdLogs.every((log) => seenLogIds.has(log.id)),
  );

  // 4. Assert pagination meta
  if (lastPagination) {
    TestValidator.equals("total records matches injected logs")(
      lastPagination.records,
    )(createdLogs.length);
    TestValidator.equals("pages matches")(lastPagination.pages)(numPages);
  }

  // 5. Structure validation (already typia.assert for every response)
  // Also, check no data loss/corruption for core fields
  for (const created of createdLogs) {
    const found = unionLogs.find((l) => l.id === created.id);
    TestValidator.predicate("log details should match")(
      !!found &&
        found.actor_id === created.actor_id &&
        found.action_type === created.action_type &&
        found.actor_type === created.actor_type,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 활동 로그를 admin 권한으로 기간 필터별 검색하는 기능 검증
 *
 * - 관리자를 새로 생성/인증한 뒤,
 * - 다양한 action_timestamp(지난달, 경계값, 최근 1주일 등)를 가진 여러 활동 로그를 저장하고
 * - 최근 1주일 기간만 포함하는 search 요청을 보내, 반환된 로그들의 action_timestamp이 정확히 지정한 구간 내인지,
 *   pagination이 정확한지 모두 점검합니다.
 *
 * 테스트 절차
 *
 * 1. 관리자 계정 생성/권한 부여
 * 2. 액티비티 로그 6개 등록:
 *
 *    - 2개: 범위 밖 (2주 전, 10일 전)
 *    - 2개: 구간 경계값 (정확히 7일 전, 오늘)
 *    - 2개: 범위 내 (3일 전, 1일 전)
 * 3. 최근 7일 구간 검색: action_timestamp_from=7일전 0시, to=오늘(테스트 실행 시각 기준)
 * 4. 반환된 로그들의 action_timestamp이 지정 구간 내에 모두 속하는지, 범위 경계치(=from/to)에 해당하는 로그도 모두
 *    포함되는지 검증
 * 5. Pagination meta(현재/페이지 크기/전체개수/페이지수) 일관성 검증
 */
export async function test_api_discussionBoard_test_search_activity_logs_with_time_interval_filter(
  connection: api.IConnection,
) {
  // 1. 관리자 계정 생성 및 인증 권한 획득
  const adminIdentifier = `admin-${RandomGenerator.alphaNumeric(8)}`;
  const grantNow = new Date().toISOString();
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        user_identifier: adminIdentifier,
        granted_at: grantNow,
        revoked_at: null,
      },
    },
  );
  typia.assert(admin);

  // 2. 테스팅용 로그: 기준일자 정의(오늘, 1일 전, 3일 전, 7일 전, 10일 전, 2주전)
  const now = new Date();
  const today = now;
  const minusDays = (days: number) => {
    const dt = new Date(now.getTime());
    dt.setDate(dt.getDate() - days);
    dt.setHours(0, 0, 0, 0);
    return dt;
  };

  const timestamps = [
    minusDays(14), // 범위 밖(2주 전)
    minusDays(10), // 범위 밖(10일 전)
    minusDays(7), // 경계(7일 전,시작)
    minusDays(3), // 범위 내(3일 전)
    minusDays(1), // 범위 내(1일 전)
    today, // 경계(오늘,끝)
  ];
  // 샘플 로그 데이터 생성
  const logs: IDiscussionBoardActivityLog[] = [];
  for (let i = 0; i < timestamps.length; ++i) {
    const log = await api.functional.discussionBoard.admin.activityLogs.create(
      connection,
      {
        body: {
          actor_id: admin.id,
          actor_type: "admin",
          action_type: `test_action_${i}`,
          action_timestamp: timestamps[i].toISOString(),
          // topic,thread,post,ip,user_agent,meta는 랜덤/노출되지 않음
        } satisfies IDiscussionBoardActivityLog.ICreate,
      },
    );
    typia.assert(log);
    logs.push(log);
  }
  // 3. 최근 1주일 구간: from ~ to(오늘)
  const action_timestamp_from = timestamps[2].toISOString(); // 7일 전 0시
  const action_timestamp_to = today.toISOString(); // 오늘 시각

  const searchResult =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        action_timestamp_from,
        action_timestamp_to,
        // (추가필드는 기본값/미사용)
      },
    });
  typia.assert(searchResult);

  // 4. 반환된 로그: action_timestamp이 정확히 구간 내? (경계 포함)
  for (const log of searchResult.data) {
    const ts = new Date(log.action_timestamp);
    TestValidator.predicate("log action_timestamp >= action_timestamp_from")(
      ts >= new Date(action_timestamp_from),
    );
    TestValidator.predicate("log action_timestamp <= action_timestamp_to")(
      ts <= new Date(action_timestamp_to),
    );
  }
  // 5. pagination structure
  const { pagination, data } = searchResult;
  TestValidator.predicate("pagination current >= 1")(pagination.current >= 1);
  TestValidator.predicate("pagination limit >= 1")(pagination.limit >= 1);
  TestValidator.predicate("pagination records >= 0")(pagination.records >= 0);
  TestValidator.predicate("pagination pages >= 1")(pagination.pages >= 1);
  TestValidator.predicate("data.length <= pagination.limit")(
    data.length <= pagination.limit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 활동 로그 actor_type(예: member와 admin)의 검색 필터링 동작을 검증합니다.
 *
 * 1. Member 타입 행위자, admin 타입 행위자 각각에 대해 예시 로그 데이터를 생성합니다.
 * 2. Actor_type별로 각각 검색 요청을 보냅니다.
 * 3. 실제 검색 결과의 각 로그가 요청한 actor_type만을 포함하는지 검증합니다.
 * 4. Page/limit 등 기본 페이징 옵션도 일부 조합 시험합니다.
 * 5. 서로 다른 actor_type이 혼재된 데이터 상황에서도 필터가 정확히 동작하는지 확인합니다.
 */
export async function test_api_discussionBoard_test_search_activity_logs_by_actor_type(
  connection: api.IConnection,
) {
  // 1. member role, admin role별로 샘플 로그 2건씩 생성 (총 4)
  const memberActorId = typia.random<string & tags.Format<"uuid">>();
  const adminActorId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();

  // member 타입 로그 생성
  const createdMember1 =
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        actor_id: memberActorId,
        actor_type: "member",
        action_type: "view_post",
        action_timestamp: new Date(now.getTime() - 10000).toISOString(),
      } satisfies IDiscussionBoardActivityLog.ICreate,
    });
  typia.assert(createdMember1);
  const createdMember2 =
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        actor_id: memberActorId,
        actor_type: "member",
        action_type: "comment_created",
        action_timestamp: new Date(now.getTime() - 9000).toISOString(),
      } satisfies IDiscussionBoardActivityLog.ICreate,
    });
  typia.assert(createdMember2);

  // admin 타입 로그 생성
  const createdAdmin1 =
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        actor_id: adminActorId,
        actor_type: "admin",
        action_type: "moderation_action",
        action_timestamp: new Date(now.getTime() - 8000).toISOString(),
      } satisfies IDiscussionBoardActivityLog.ICreate,
    });
  typia.assert(createdAdmin1);
  const createdAdmin2 =
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        actor_id: adminActorId,
        actor_type: "admin",
        action_type: "post_created",
        action_timestamp: new Date(now.getTime() - 7000).toISOString(),
      } satisfies IDiscussionBoardActivityLog.ICreate,
    });
  typia.assert(createdAdmin2);

  // 2. actor_type: member로만 검색해서 결과가 전부 member인지 확인
  const memberSearch =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        actor_type: "member",
      } satisfies IDiscussionBoardActivityLog.IRequest,
    });
  typia.assert(memberSearch);
  for (const log of memberSearch.data)
    TestValidator.equals("only member rows")(log.actor_type)("member");

  // 3. actor_type: admin 으로만 검색해서 결과가 전부 admin인지 확인
  const adminSearch =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        actor_type: "admin",
      } satisfies IDiscussionBoardActivityLog.IRequest,
    });
  typia.assert(adminSearch);
  for (const log of adminSearch.data)
    TestValidator.equals("only admin rows")(log.actor_type)("admin");

  // 4. actor_type + 페이징
  const pagedMemberSearch =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        actor_type: "member",
        page: 1,
        limit: 1,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    });
  typia.assert(pagedMemberSearch);
  for (const log of pagedMemberSearch.data)
    TestValidator.equals("only member rows - paged")(log.actor_type)("member");

  const pagedAdminSearch =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        actor_type: "admin",
        page: 1,
        limit: 2,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    });
  typia.assert(pagedAdminSearch);
  for (const log of pagedAdminSearch.data)
    TestValidator.equals("only admin rows - paged")(log.actor_type)("admin");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that searching activity logs as a non-admin member is properly
 * forbidden.
 *
 * This test confirms that non-administrative users cannot access the advanced
 * audit log search API endpoint intended for admins.
 *
 * 1. Create a member using the admin API.
 * 2. Simulate a member (or unauthenticated) session by removing Authorization from
 *    the connection ensuring the credentials do not have admin privileges.
 * 3. Attempt to perform a PATCH search for activity logs with this non-admin
 *    session.
 * 4. Confirm that access is denied by asserting an error is thrown.
 */
export async function test_api_discussionBoard_test_activity_logs_search_forbidden_for_non_admins(
  connection: api.IConnection,
) {
  // 1. Admin creates a member via admin-only endpoint
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: RandomGenerator.alphabets(12),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Simulate a non-admin session by removing Authorization from the connection
  const nonAdminConnection: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(
        ([key]) => key.toLowerCase() !== "authorization",
      ),
    ),
  };

  // 3. Attempt to PATCH search activity logs as a non-admin (should be forbidden)
  await TestValidator.error("activity log search forbidden for non-admin")(
    async () => {
      await api.functional.discussionBoard.admin.activityLogs.search(
        nonAdminConnection,
        {
          body: {}, // No specific filter; any request should be forbidden for non-admins
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 활동 로그 비어있는 결과 필터링 동작 검증
 *
 * 관리자 감사 로그를 원하는 검색창(시간 범위 등)으로 조회할 때, 해당 범위 내에 일치하는 로그가 하나도 없으면 결과 데이터 배열이 비어
 * 있어야 하며, 에러가 발생하지 않아야 함을 검증한다.
 *
 * 1. 사전에, 테스트용 검색 범위(필터 윈도우) 바깥에 충분히 과거 시점(예: 2022년) 로그를 1건 생성해둔다. (즉, DB가 완전히
 *    비어있지는 않은 상태!)
 * 2. 아주 최근 시점(예: 2025년)으로 action_timestamp 검색 범위를 limit으로 하는 조건으로 로그를 검색한다.
 * 3. 반환된 data 배열은 빈 배열이어야 하며, pagination 값은 정상적으로 반환되고, 에러가 없어야 한다.
 *
 * 성공: 에러 없이 정상적으로 빈 배열이 반환되는 것 실패: 빈 결과가 아닌 경우, 또는 에러가 발생할 경우
 */
export async function test_api_discussionBoard_test_search_activity_logs_returns_no_results_for_empty_range(
  connection: api.IConnection,
) {
  // 1. 과거 시점 로그 생성: 2022년 1월 1일 00:00:00 UTC
  const oldLog = await api.functional.discussionBoard.admin.activityLogs.create(
    connection,
    {
      body: {
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        actor_type: "admin",
        action_type: "manual_test",
        action_timestamp: "2022-01-01T00:00:00.000Z",
        topic_id: null,
        thread_id: null,
        post_id: null,
        ip_address: null,
        user_agent: null,
        metadata_json: null,
      } satisfies IDiscussionBoardActivityLog.ICreate,
    },
  );
  typia.assert(oldLog);

  // 2. 최근(미래)시점만을 검색 필터로 지정 (예: 2025~2026년)
  const recentFrom = "2025-01-01T00:00:00.000Z";
  const recentTo = "2025-12-31T23:59:59.999Z";

  const searchResult =
    await api.functional.discussionBoard.admin.activityLogs.search(connection, {
      body: {
        action_timestamp_from: recentFrom,
        action_timestamp_to: recentTo,
        limit: 20,
        page: 1,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    });
  typia.assert(searchResult);

