    );
    TestValidator.predicate("has created_at")(
      !!c.created_at && typeof c.created_at === "string",
    );
    TestValidator.predicate("has updated_at")(
      !!c.updated_at && typeof c.updated_at === "string",
    );
    const allowedSummaryFields = [
