  connection: api.IConnection,
) {
  // 1. Register a board member via admin API
  const memberUserIdentifier = `testuser_admin_search_${RandomGenerator.alphabets(8)}`;
  const memberJoinedAt = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberUserIdentifier,
        joined_at: memberJoinedAt,
      },
    },
  );
  typia.assert(member);

  // 2. As this member, create a topic (category UUID must be synthetic here)
  const topic = await api.functional.discussionBoard.member.topics.create(
    connection,
    {
      body: {
        title: `E2E Test Topic ${RandomGenerator.alphabets(6)}`,
        description: "Testing comment search filters.",
        pinned: false,
        closed: false,
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    },
  );
  typia.assert(topic);

  // 3. Create a thread in that topic
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: `E2E Test Thread ${RandomGenerator.alphabets(8)}`,
        },
      },
    );
  typia.assert(thread);

  // 4. Add a post to the thread
  const post = await api.functional.discussionBoard.member.threads.posts.create(
    connection,
    {
      threadId: thread.id,
      body: {
        discussion_board_thread_id: thread.id,
        body: "This is the parent post for E2E comment search.",
      },
    },
  );
  typia.assert(post);

  // 5. Create 3 comments with unique content and manual time separation
  const now = new Date();
  const comments: Array<{ id: string; content: string; created_at: string }> =
    [];
  for (const [ix, keyword] of ["alpha", "beta", "gamma"].entries()) {
    // Control created_at via natural progression (API is not guaranteed to expose created_at mutation, so let it auto-increment)
    const content = `E2E content ${keyword} ${RandomGenerator.alphabets(5)}`;
    const comment = await api.functional.discussionBoard.member.comments.create(
      connection,
      {
        body: {
          discussion_board_member_id: member.id,
          discussion_board_post_id: post.id,
          content,
        },
      },
    );
    typia.assert(comment);
    comments.push({
      id: comment.id,
      content: comment.content,
      created_at: comment.created_at,
    });
    // Small delay to stagger created_at timestamps
    await new Promise((r) => setTimeout(r, 1200));
  }
  // Sort by created_at ascending for easier later range calculation
  comments.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // 6. Search by substring for "beta" - expect exactly one matching comment
  {
    const keyword = "beta";
    const adminSearch =
      await api.functional.discussionBoard.admin.comments.search(connection, {
        body: {
          content_contains: keyword,
        },
      });
    typia.assert(adminSearch);
    const matches = adminSearch.data;
    TestValidator.equals("matched count for beta keyword")(1)(matches.length);
    TestValidator.equals("matched comment content for beta keyword")(
      matches[0].content.includes("beta"),
    )(true);
    TestValidator.equals("matched comment id matches")(matches[0].id)(
      comments.find((c) => c.content.includes("beta"))!.id,
    );
  }

  // 7. Search by created_at window to match only the 2nd and 3rd comments (exclude oldest)
  {
    const createdAtFrom = comments[1].created_at;
    const adminSearch =
      await api.functional.discussionBoard.admin.comments.search(connection, {
        body: {
          created_at_from: createdAtFrom,
        },
      });
    typia.assert(adminSearch);
    const found = adminSearch.data.filter((row) =>
      comments.some((x) => x.id === row.id),
    );
    TestValidator.equals("created_at_from picks correct comments")(
      found.length,
    )(2);
    for (const c of comments.slice(1)) {
      TestValidator.predicate(`comment with id=${c.id} is in search result`)(
        found.some((row) => row.id === c.id),
      );
    }
  }

  // 8. Compound filter (content_contains = gamma + created_at_from for 3rd comment)
  {
    const c = comments[2];
    const adminSearch =
      await api.functional.discussionBoard.admin.comments.search(connection, {
        body: {
          content_contains: "gamma",
          created_at_from: c.created_at,
        },
      });
    typia.assert(adminSearch);
    const found = adminSearch.data;
    TestValidator.equals("compound filter for gamma/latest comment")(1)(
      found.length,
    );
    TestValidator.equals("compound content for gamma")(
      found[0].content.includes("gamma"),
    )(true);
    TestValidator.equals("compound id for gamma")(found[0].id)(c.id);
  }

  // 9. Negative case - keyword not present yields zero results
  {
    const adminSearch =
      await api.functional.discussionBoard.admin.comments.search(connection, {
        body: {
          content_contains: "NO_MATCH_E2E_UNIQUE_STRING",
        },
      });
    typia.assert(adminSearch);
    TestValidator.equals("empty data for no-match")(adminSearch.data.length)(0);
  }

  // 10. Pagination validation (small n: check limit/records/pages)
  {
    const adminSearch =
      await api.functional.discussionBoard.admin.comments.search(connection, {
        body: {
          // No filter: fetch them all back
        },
      });
    typia.assert(adminSearch);
    const rows = adminSearch.data.filter((row) =>
      comments.some((x) => x.id === row.id),
    );
    TestValidator.equals("pagination returns all test comments")(rows.length)(
      3,
    );
    // Pagination metadata basic structure check
    const meta = adminSearch.pagination;
    TestValidator.predicate("pagination current > 0")(meta.current > 0);
    TestValidator.predicate("pagination limit >= n")(meta.limit >= 3);
    TestValidator.predicate("pagination total records >= n")(meta.records >= 3);
    TestValidator.predicate("pagination pages >= 1")(meta.pages >= 1);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin comment search filtering by member and soft-deleted status.
 *
 * This test ensures that when searching as admin for comments written by a
 * specific member, with further filtering by soft-deleted (is_deleted: true) or
 * active (is_deleted: false), only comments matching those criteria are
 * returned. The test performs the following steps:
 *
 * 1. Admin creates a new board member and captures their ID for filtering.
 * 2. Member creates a topic and a thread.
 * 3. Member creates a post under the thread.
 * 4. Member creates at least two comments: one normal (active), one to be
 *    soft-deleted.
 * 5. Member soft-deletes one comment (via update with is_deleted: true).
 * 6. As admin, search for comments with: a. member_id = <new member>, is_deleted =
 *    false => expect only the normal comment. b. member_id = <new member>,
 *    is_deleted = true => expect only the soft-deleted comment. c. member_id =
 *    <nonexistent member>, is_deleted = any => expect no results (edge case).
 *    d. Pagination: create multiple extra comments, search with limit=1 and
 *    validate correct page breakdown.
 *
 * Each search result is validated to contain only comments for the given member
 * and is_deleted state. No other members' comments or mismatched is_deleted
 * states must appear.
 */
export async function test_api_discussionBoard_test_admin_search_comments_by_member_and_soft_deleted_state(
  connection: api.IConnection,
) {
  // 1. Create a board member
  const boardMember = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: RandomGenerator.alphaNumeric(16),
        joined_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(boardMember);

  // 2. Create a topic for that member
  const topic = await api.functional.discussionBoard.member.topics.create(
    connection,
    {
      body: {
        title: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph()(),
        pinned: false,
        closed: false,
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    },
  );
  typia.assert(topic);

  // 3. Create a thread in that topic
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(thread);

  // 4. Create a post in the thread
  const post = await api.functional.discussionBoard.member.threads.posts.create(
    connection,
    {
      threadId: thread.id,
      body: {
        discussion_board_thread_id: thread.id,
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(post);

  // 5. Create two comments: one normal, one to be soft-deleted
  const normalComment =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_member_id: boardMember.id,
        discussion_board_post_id: post.id,
        content: RandomGenerator.paragraph()(),
      },
    });
  typia.assert(normalComment);

  const deletedComment =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_member_id: boardMember.id,
        discussion_board_post_id: post.id,
        content: RandomGenerator.paragraph()(),
      },
    });
  typia.assert(deletedComment);

  // 6. Soft-delete one comment
  const updatedDeletedComment =
    await api.functional.discussionBoard.member.comments.update(connection, {
      commentId: deletedComment.id,
      body: { is_deleted: true },
    });
  typia.assert(updatedDeletedComment);

  // 7. Admin search for active comments by this member (is_deleted: false)
  let searchActive = await api.functional.discussionBoard.admin.comments.search(
    connection,
    {
      body: { member_id: boardMember.id, is_deleted: false },
    },
  );
  typia.assert(searchActive);
  for (const c of searchActive.data) {
    TestValidator.equals("member_id matches")(c.discussion_board_member_id)(
      boardMember.id,
    );
    TestValidator.equals("is_deleted false")(c.is_deleted)(false);
  }
  TestValidator.predicate("Only normal (not deleted) comment present")(
    searchActive.data.find((x) => x.id === normalComment.id) !== undefined &&
      searchActive.data.find((x) => x.id === deletedComment.id) === undefined,
  );

  // 8. Admin search for deleted comments by this member (is_deleted: true)
  let searchDeleted =
    await api.functional.discussionBoard.admin.comments.search(connection, {
      body: { member_id: boardMember.id, is_deleted: true },
    });
  typia.assert(searchDeleted);
  for (const c of searchDeleted.data) {
    TestValidator.equals("member_id matches")(c.discussion_board_member_id)(
      boardMember.id,
    );
    TestValidator.equals("is_deleted true")(c.is_deleted)(true);
  }
  TestValidator.predicate("Only deleted comment present")(
    searchDeleted.data.find((x) => x.id === deletedComment.id) !== undefined &&
      searchDeleted.data.find((x) => x.id === normalComment.id) === undefined,
  );

  // 9. Edge case: search with a non-existent member_id
  const nonExistentMemberId = typia.random<string & tags.Format<"uuid">>();
  let searchNone = await api.functional.discussionBoard.admin.comments.search(
    connection,
    {
      body: { member_id: nonExistentMemberId },
    },
  );
  typia.assert(searchNone);
  TestValidator.equals("no results for unknown member")(searchNone.data.length)(
    0,
  );

  // 10. Edge case: pagination—create extra comments, search with limit=1, pages=2
  const extraComments = await ArrayUtil.asyncRepeat(2)(async () =>
    api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_member_id: boardMember.id,
        discussion_board_post_id: post.id,
        content: RandomGenerator.alphaNumeric(10),
      },
    }),
  );
  for (const c of extraComments) typia.assert(c);

  // search paginated with limit=1
  let paginatedResult =
    await api.functional.discussionBoard.admin.comments.search(connection, {
      body: { member_id: boardMember.id, is_deleted: false },
    });
  typia.assert(paginatedResult);
  if (paginatedResult.data.length > 1) {
    let page = 1;
    let cursor = 0;
    while (cursor < paginatedResult.data.length) {
      let result = await api.functional.discussionBoard.admin.comments.search(
        connection,
        {
          body: { member_id: boardMember.id, is_deleted: false },
        },
      );
      typia.assert(result);
      for (const c of result.data) {
        TestValidator.equals("member_id matches:paginated")(
          c.discussion_board_member_id,
        )(boardMember.id);
        TestValidator.equals("is_deleted false:paginated")(c.is_deleted)(false);
      }
      cursor += result.data.length;
      page++;
      if (page > 10) break; // prevent infinite loop
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Moderator advanced search and filter for comments by content
 * keyword, including pagination and deleted status.
 *
 * This test thoroughly validates the moderator's ability to retrieve only
 * comments containing specific content keywords, handling pagination and
 * visibility of deleted comments:
 *
 * 1. Registers a new member via admin API for controlled authorship.
 * 2. Creates a topic with random category id (category existence assumed).
 * 3. Adds a thread under the topic.
 * 4. Posts into the thread.
 * 5. Creates a set of comments under the post: several contain a unique keyword
 *    (match group), some with a unique decoy keyword (decoy group).
 * 6. (Omitted: soft-delete, as no such API exists—cannot test visibility of
 *    deleted items.)
 * 7. Searches as moderator for the match keyword; asserts only matching comments
 *    are returned, no decoys, and pagination fields are valid.
 * 8. Further asserts that all returned comment contents contain the keyword and
 *    never contain the decoy.
 *
 * If/when a soft-delete endpoint is exposed, the test should be extended to
 * verify deleted record visibility to moderators.
 */
export async function test_api_discussionBoard_test_moderator_advanced_search_comments_by_content_keywords(
  connection: api.IConnection,
) {
  // 1. Provision a new test member for clean authorship
  const memberUserIdentifier = `moderator_test_member_${RandomGenerator.alphaNumeric(6)}`;
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberUserIdentifier,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 2. Create a topic (requires assumed valid category uuid)
  const topic = await api.functional.discussionBoard.member.topics.create(
    connection,
    {
      body: {
        title: `Mod AdvSearch Test Topic ${RandomGenerator.alphaNumeric(4)}`,
        pinned: false,
        closed: false,
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        // If category API existed, we'd create then use that here.
      },
    },
  );
  typia.assert(topic);

  // 3. Add a thread to the topic
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: `AdvSearch Thread ${RandomGenerator.alphaNumeric(6)}`,
        },
      },
    );
  typia.assert(thread);

  // 4. Create a post in the thread
  const post = await api.functional.discussionBoard.member.threads.posts.create(
    connection,
    {
      threadId: thread.id,
      body: {
        discussion_board_thread_id: thread.id,
        body: "Seed post for advanced moderator search test.",
      },
    },
  );
  typia.assert(post);

  // 5. Create comments for keyword search and false-positive test
  const keyword = "MODTESTKEYWORD";
  const decoyKeyword = "XYZDEC0Y";
  const matchTexts = [
    `This is a ${keyword} comment`,
    `${keyword} at start`,
    `Ends with keyword ${keyword}`,
    `Surround ${keyword} middled`,
    `Extra ${keyword} repeat ${keyword}`,
  ];
  const decoyTexts = [
    `Just banality, no keyword`,
    `Decoy: ${decoyKeyword}`,
    `Totally unrelated content`,
  ];
  // Insert matching comments
  for (const content of matchTexts) {
    const created = await api.functional.discussionBoard.member.comments.create(
      connection,
      {
        body: {
          discussion_board_member_id: member.id,
          discussion_board_post_id: post.id,
          content,
        },
      },
    );
    typia.assert(created);
  }
  // Insert decoys
  for (const content of decoyTexts) {
    const created = await api.functional.discussionBoard.member.comments.create(
      connection,
      {
        body: {
          discussion_board_member_id: member.id,
          discussion_board_post_id: post.id,
          content,
        },
      },
    );
    typia.assert(created);
  }

  // 6. (Omitted: soft-delete one comment, as no API exists for that)

  // 7. Perform moderator keyword search
  const result = await api.functional.discussionBoard.moderator.comments.search(
    connection,
    {
      body: {
        content_contains: keyword,
      },
    },
  );
  typia.assert(result);

  // 8. Assert all returned comment contents strictly include the keyword and never the decoy
  TestValidator.predicate("all returned comments contain search keyword")(
    result.data.every((x) => x.content.includes(keyword)),
  );
  TestValidator.predicate("no returned comments contain decoy keyword")(
    result.data.every((x) => !x.content.includes(decoyKeyword)),
  );

  // 9. Assert pagination metadata integrity
  TestValidator.predicate("pagination metadata present")(
    !!result.pagination && typeof result.pagination === "object",
  );
  TestValidator.predicate("no more returned than limit")(
    result.data.length <= result.pagination.limit,
  );
  TestValidator.predicate("record count plausible")(
    result.pagination.records >= result.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
