import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";

/**
 * Validate prevention of thread title duplication within a topic upon update.
 *
 * This test simulates a business scenario in which the system must enforce the
 * business rule that thread titles within the same topic are unique, not just
 * on creation, but also when attempting to update an existing thread.
 *
 * Step-by-step process:
 *
 * 1. Register a board member who will create and update threads.
 * 2. Create a topic under which threads will be tested for duplicate title
 *    constraints.
 * 3. Create two threads under this topic, each with a unique title.
 * 4. Attempt to update the second thread's title to match the first thread's
 *    title. This should be rejected by the API due to the uniqueness
 *    constraint.
 * 5. (Optional) Verifying that the thread's title is unchanged post-failure is
 *    omitted due to lack of a 'get by id' endpoint in provided SDK.
 */
export async function test_api_discussionBoard_test_update_thread_fail_due_to_duplicate_title_in_topic(
  connection: api.IConnection,
) {
  // 1. Register a board member
  const memberUserId: string = RandomGenerator.alphaNumeric(12);
  const joinTime: string = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberUserId,
        joined_at: joinTime,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a topic (category id is randomized for test independence)
  const topicTitle = RandomGenerator.paragraph()(1).trim();
  const topic = await api.functional.discussionBoard.admin.topics.create(
    connection,
    {
      body: {
        title: topicTitle,
        pinned: false,
        closed: false,
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        description: RandomGenerator.paragraph()(1),
      } satisfies IDiscussionBoardTopics.ICreate,
    },
  );
  typia.assert(topic);

  // 3. Create two threads with unique titles in the topic
  const threadTitle1 = RandomGenerator.paragraph()(1).trim();
  const threadTitle2 = RandomGenerator.paragraph()(1).trim();

  const thread1 =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: threadTitle1,
        } satisfies IDiscussionBoardThreads.ICreate,
      },
    );
  typia.assert(thread1);

  const thread2 =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: threadTitle2,
        } satisfies IDiscussionBoardThreads.ICreate,
      },
    );
  typia.assert(thread2);

  // 4. Attempt to update second thread's title to be the same as the first (should error)
  await TestValidator.error("duplicate thread title update should be rejected")(
    async () => {
      await api.functional.discussionBoard.member.topics.threads.update(
        connection,
        {
          topicId: topic.id,
          threadId: thread2.id,
          body: {
            title: threadTitle1,
          } satisfies IDiscussionBoardThreads.IUpdate,
        },
      );
    },
  );

  // 5. (Optional): Cannot re-fetch thread to confirm unchanged title (no endpoint provided)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";

/**
 * Verify that an unauthorized member (not the thread creator) cannot update
 * another member's thread.
 *
 * This test verifies proper enforcement of thread ownership and permissions by
 * the API. Specifically, it ensures that only the thread's creator (or
 * privileged users) may update its metadata, and other members are denied such
 * updates.
 *
 * Test Flow:
 *
 * 1. Register Member A (thread creator) using the admin API.
 * 2. Register Member B (unauthorized member) using the admin API.
 * 3. Create a topic using the admin API. Since category creation is not available
 *    via API, a random UUID will be used for category ID.
 * 4. Have Member A create a thread in the created topic (context switching is
 *    hypothetical—actual session simulation is out of scope).
 * 5. Attempt to update the thread as Member B: API call should fail due to lack of
 *    ownership/permission.
 *
 * The test confirms the API rejects unauthorized update attempts and enforces
 * correct thread permissions.
 */
export async function test_api_discussionBoard_test_update_thread_fail_unauthorized_member_not_owner(
  connection: api.IConnection,
) {
  // 1. Register Member A (thread creator)
  const memberA_user_identifier =
    RandomGenerator.alphabets(12) + "@example.com";
  const memberA_joined_at = new Date().toISOString();
  const memberA = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberA_user_identifier,
        joined_at: memberA_joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberA);

  // 2. Register Member B (unauthorized updater)
  const memberB_user_identifier =
    RandomGenerator.alphabets(12) + "@example.com";
  const memberB_joined_at = new Date().toISOString();
  const memberB = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberB_user_identifier,
        joined_at: memberB_joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberB);

  // 3. Create a topic (simulate category by generating a random UUID for discussion_board_category_id)
  const category_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const topic_title = RandomGenerator.paragraph()(1);
  const topic = await api.functional.discussionBoard.admin.topics.create(
    connection,
    {
      body: {
        title: topic_title,
        description: RandomGenerator.paragraph()(2),
        pinned: false,
        closed: false,
        discussion_board_category_id: category_id,
      } satisfies IDiscussionBoardTopics.ICreate,
    },
  );
  typia.assert(topic);

  // 4. Have Member A create a thread in the topic
  const thread_title = RandomGenerator.paragraph()(1);
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: thread_title,
        } satisfies IDiscussionBoardThreads.ICreate,
      },
    );
  typia.assert(thread);
  TestValidator.equals("topic-id of thread matches")(
    thread.discussion_board_topic_id,
  )(topic.id);
  TestValidator.equals("thread creator is Member A")(thread.creator_member_id)(
    memberA.id,
  );

  // 5. Attempt to update the thread as Member B
  // In a full system we'd switch sessions or tokens to Member B—here, context simulation suffices.
  // The update should fail because Member B is not the owner.
  const updateTitle =
    RandomGenerator.paragraph()(1) + " (unauthorized update attempt)";
  await TestValidator.error(
    "unauthorized update of thread by non-owner should be rejected",
  )(async () => {
    await api.functional.discussionBoard.member.topics.threads.update(
      connection,
      {
        topicId: topic.id,
        threadId: thread.id,
        body: {
          title: updateTitle,
        } satisfies IDiscussionBoardThreads.IUpdate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";

/**
 * Validate that a moderator can update any thread within a topic, regardless of
 * the original creator.
 *
 * This test simulates a realistic forum workflow:
 *
 * 1. Register a new member (who will become the thread's creator)
 * 2. Register a new moderator (with separate identity)
 * 3. Create a topic (as admin)
 * 4. As the member, create a thread in that topic
 * 5. As the moderator, update the thread's title
 * 6. Verify that the update succeeds and audit fields are correct
 *
 * This ensures moderator privilege overrides thread ownership for editing
 * rights.
 */
export async function test_api_discussionBoard_test_update_thread_by_moderator_success(
  connection: api.IConnection,
) {
  // 1. Register a new board member (thread creator)
  const member_user_identifier = RandomGenerator.alphabets(12);
  const member_joined_at = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: member_user_identifier,
        joined_at: member_joined_at,
      },
    },
  );
  typia.assert(member);

  // 2. Register a new moderator (separate identity)
  const moderator_user_identifier = RandomGenerator.alphabets(12);
  const moderator_granted_at = new Date().toISOString();
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        user_identifier: moderator_user_identifier,
        granted_at: moderator_granted_at,
        revoked_at: null,
      },
    });
  typia.assert(moderator);

  // 3. Create a topic (as admin)
  const topic_title = RandomGenerator.alphabets(15);
  const topic_category_id = typia.random<string & tags.Format<"uuid">>();
  const topic = await api.functional.discussionBoard.admin.topics.create(
    connection,
    {
      body: {
        title: topic_title,
        description: "Test topic for moderator update thread scenario.",
        pinned: false,
        closed: false,
        discussion_board_category_id: topic_category_id,
      },
    },
  );
  typia.assert(topic);

  // 4. As member, create a thread in the topic
  // (Assume role switching handled by test automation context)
  const thread_title = RandomGenerator.alphabets(16);
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: thread_title,
        },
      },
    );
  typia.assert(thread);

  // 5. As moderator, update the thread's title
  const new_thread_title = thread_title + "_updated";
  const updated_thread =
    await api.functional.discussionBoard.moderator.topics.threads.update(
      connection,
      {
        topicId: topic.id,
        threadId: thread.id,
        body: {
          title: new_thread_title,
        },
      },
    );
  typia.assert(updated_thread);

  // 6. Verify the changes and audit trail
  TestValidator.equals("thread id unchanged")(updated_thread.id)(thread.id);
  TestValidator.equals("topic relation unchanged")(
    updated_thread.discussion_board_topic_id,
  )(topic.id);
  TestValidator.equals("creator member unchanged")(
    updated_thread.creator_member_id,
  )(thread.creator_member_id);
  TestValidator.notEquals("title updated")(updated_thread.title)(thread.title);
  TestValidator.equals("title is as updated")(updated_thread.title)(
    new_thread_title,
  );
  TestValidator.predicate("updated_at not before created_at")(
    new Date(updated_thread.updated_at).getTime() >=
      new Date(thread.created_at).getTime(),
  );
  TestValidator.predicate("updated_at changes")(
    updated_thread.updated_at !== thread.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";

/**
 * Validate input constraints for updating threads as a moderator: blank or
 * overlength titles should fail.
 *
 * Scenario:
 *
 * 1. Create admin-controlled moderator and member via API (for test isolation).
 * 2. Admin creates topic for the test.
 * 3. Member creates thread with a valid title in the topic.
 * 4. As moderator, attempt to update thread title to '' (blank string) and to an
 *    overlength string (>255 chars).
 * 5. Assert that both attempts result in input validation error (error thrown).
 *
 * Steps:
 *
 * - Moderator created via POST /discussionBoard/admin/moderators and retains
 *   token via connection.
 * - Member created via POST /discussionBoard/admin/members.
 * - Topic created via POST /discussionBoard/admin/topics.
 * - Thread created by member via POST
 *   /discussionBoard/member/topics/{topicId}/threads.
 * - Switch to moderator, perform updates using PUT
 *   /discussionBoard/moderator/topics/{topicId}/threads/{threadId} with invalid
 *   titles.
 * - Validate errors are thrown as expected.
 */
export async function test_api_discussionBoard_test_update_thread_with_invalid_title_moderator(
  connection: api.IConnection,
) {
  // 1. Admin creates moderator user
  const moderator_identifier = typia.random<string>();
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        user_identifier: moderator_identifier,
        granted_at: new Date().toISOString(),
        revoked_at: null,
      },
    });
  typia.assert(moderator);

  // 2. Admin creates member user (thread creator)
  const member_identifier = typia.random<string>();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: member_identifier,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. Admin creates topic
  const topic = await api.functional.discussionBoard.admin.topics.create(
    connection,
    {
      body: {
        title: RandomGenerator.alphaNumeric(16),
        description: RandomGenerator.alphaNumeric(32),
        pinned: false,
        closed: false,
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    },
  );
  typia.assert(topic);

  // 4. Member creates a valid thread in the topic
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: RandomGenerator.alphaNumeric(8),
        },
      },
    );
  typia.assert(thread);

  // 5.a. Moderator tries to set blank title
  await TestValidator.error("should reject blank title")(() =>
    api.functional.discussionBoard.moderator.topics.threads.update(connection, {
      topicId: topic.id,
      threadId: thread.id,
      body: { title: "" },
    }),
  );

  // 5.b. Moderator tries to set too-long title (e.g. 300 chars)
  const longTitle = RandomGenerator.alphaNumeric(300);
  await TestValidator.error("should reject title over length limit")(() =>
    api.functional.discussionBoard.moderator.topics.threads.update(connection, {
      topicId: topic.id,
      threadId: thread.id,
      body: { title: longTitle },
    }),
  );
}

