 * 5. 존재하지 않는 랜덤한 file_name으로 첨부파일 검색 → data가 빈 배열인지 검증
 * 6. 존재하지 않는 마임타입으로 첨부파일 검색 → data가 빈 배열인지 검증
 */
export async function test_api_discussionBoard_test_search_post_attachments_with_no_results(
