 * 1. 새로운 설정을 등록한다 (key, value, description 포함)
 * 2. 등록 결과의 id를 회수한다
 * 3. 그 id로 getBySettingid API를 호출해서 정보 일치 여부를 검증한다
 */
export async function test_api_discussionBoard_admin_settings_test_get_specific_setting_by_id_success(
