  typia.assert(result);
  TestValidator.equals("user_identifier match")(result.user_identifier)(
    user_identifier,
  );
  TestValidator.equals("granted_at match")(result.granted_at)(granted_at);
  TestValidator.equals("revoked_at match")(result.revoked_at)(revoked_at);
}

