import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";
import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Provides details for a system notice by ID (for member users).
 *
 * Returns all fields for a single, currently active and public system notice,
 * enforcing schedule rules. Non-admins cannot view inactive, expired, or
 * scheduled-future notices.
 *
 * @param props - Member: The authenticated member performing the lookup
 *   systemNoticeId: UUID of the notice to fetch
 * @returns Full detail of the system notice if visible
 * @throws {Error} When notice is not found, inactive, expired, or scheduled for
 *   the future
 */
export async function get__discussionBoard_member_systemNotices_$systemNoticeId(props: {
  member: MemberPayload;
  systemNoticeId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardSystemNotice> {
  const { systemNoticeId } = props;

  // Fetch the notice by UUID
  const record =
    await MyGlobal.prisma.discussion_board_system_notices.findUnique({
      where: { id: systemNoticeId },
    });
  if (!record) throw new Error("System notice not found");

  // Enforce visibility for member: only active & currently visible notices allowed
  const now = toISOStringSafe(new Date());
  const startOk = !record.start_at || toISOStringSafe(record.start_at) <= now;
  const endOk = !record.end_at || toISOStringSafe(record.end_at) > now;
  if (!record.is_active || !startOk || !endOk)
    throw new Error("System notice is not accessible to members.");

  return {
    id: record.id as string & tags.Format<"uuid">,
    category_id: record.category_id ?? null,
    title: record.title,
    body: record.body,
    is_active: record.is_active,
    start_at: record.start_at ? toISOStringSafe(record.start_at) : null,
    end_at: record.end_at ? toISOStringSafe(record.end_at) : null,
    created_at: toISOStringSafe(record.created_at),
    updated_at: toISOStringSafe(record.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * 시스템(글로벌 및 카테고리별) 공지사항 등록 엔드포인트
 *
 * 이 엔드포인트는 플랫폼 관리자(admin)만이 전역 또는 특정 카테고리에 표시될 시스템 공지사항을 생성할 수 있도록 허용합니다. 입력
 * 데이터에는 제목, 본문, 활성상태, 스케줄링 윈도우(start_at, end_at/둘 다 optional), 카테고리
 * 참조(optional)가 포함되며, 생성 및 수정 타임스탬프는 자동으로 설정됩니다.
 *
 * 입력 category_id가 제공되면 해당 카테고리가 실제 존재하는지 검증하며, 같은 category_id(혹은 null, 전역) 내에서
 * 제목(title)이 중복되면 에러를 반환합니다. 등록 완료 후 생성된 공지사항 엔티티(모든 필드 포함)를 반환합니다.
 *
 * @param props - 요청 속성
 * @param props.admin - 인증된 AdminPayload (관리자 식별/권한)
 * @param props.body - 신규 공지사항의 필드(제목, 본문, 활성, 스케줄/카테고리 등)
 * @returns 생성된 IDiscussionBoardSystemNotice 엔티티(전체 칼럼 반환)
 * @throws {Error} Category_id가 존재하지 않거나(title 중복), 또는 Prisma DB 오류 발생 시
 */
export async function post__discussionBoard_admin_systemNotices(props: {
  admin: AdminPayload;
  body: IDiscussionBoardSystemNotice.ICreate;
}): Promise<IDiscussionBoardSystemNotice> {
  const { admin, body } = props;

  // (1) category_id 검증 (존재여부)
  if (body.category_id !== null && body.category_id !== undefined) {
    const categoryExists =
      await MyGlobal.prisma.discussion_board_categories.findFirst({
        where: { id: body.category_id },
      });
    if (!categoryExists) {
      throw new Error(
        "Invalid category_id: 해당 카테고리가 존재하지 않습니다.",
      );
    }
  }
  // (2) (category_id, title) 유니크 체크
  const existingNotice =
    await MyGlobal.prisma.discussion_board_system_notices.findFirst({
      where: {
        category_id: body.category_id ?? null,
        title: body.title,
      },
    });
  if (existingNotice) {
    throw new Error(
      "동일 카테고리 내에 이미 같은 제목의 공지사항이 존재합니다.",
    );
  }
  // (3) id, 타임스탬프 준비
  const id = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // (4) 신규 공지 생성
  const created = await MyGlobal.prisma.discussion_board_system_notices.create({
    data: {
      id: id,
      category_id: body.category_id ?? null,
      title: body.title,
      body: body.body,
      is_active: body.is_active,
      start_at: body.start_at ?? null,
      end_at: body.end_at ?? null,
      created_at: now,
      updated_at: now,
    },
  });
  // (5) 반환 객체 필드 타입 변환/정규화
  return {
    id: created.id,
    category_id: created.category_id ?? null,
    title: created.title,
    body: created.body,
    is_active: created.is_active,
    start_at: created.start_at ? toISOStringSafe(created.start_at) : null,
    end_at: created.end_at ? toISOStringSafe(created.end_at) : null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * 시스템(글로벌 및 카테고리별) 공지사항 엔터티를 수정합니다.
 *
 * 지정된 systemNoticeId(UUID)에 해당하는 discussion_board_system_notices 레코드의 title,
 * body, is_active, category_id, start_at, end_at을 업데이트합니다. 스케줄 window(start_at,
 * end_at)가 모두 제공되는 경우 유효성(start_at <= end_at)을 검사합니다. 업데이트 후 수정시간(updated_at)을
 * 현재 시각(ISO8601)으로 갱신하며, 없는 레코드면 404(Not Found)를 반환합니다.
 *
 * 관리자(관리자 인증 필수)만 실행 가능하며, Prisma에서 반환되는 모든 Date/nullable Date 필드는 string &
 * tags.Format<'date-time'> 혹은 null로 변환되어 DTO로 반환됩니다.
 *
 * @param props - 요청 속성 객체
 * @param props.admin - 인증된 관리자 페이로드
 * @param props.systemNoticeId - 수정할 system notice의 UUID (PK)
 * @param props.body - 공지사항 업데이트 필드(title, body, is_active, category_id,
 *   start_at, end_at)
 * @returns 수정 완료된 system notice DTO
 * @throws {Error} 스케줄 윈도우가 잘못된 경우(start_at > end_at)
 * @throws {Error} 대상 systemNoticeId가 존재하지 않을 경우(404)
 */
export async function put__discussionBoard_admin_systemNotices_$systemNoticeId(props: {
  admin: AdminPayload;
  systemNoticeId: string & tags.Format<"uuid">;
  body: IDiscussionBoardSystemNotice.IUpdate;
}): Promise<IDiscussionBoardSystemNotice> {
  const { admin, systemNoticeId, body } = props;

  // 존재여부 체크 (없는 경우 prisma가 404 throw)
  const notice =
    await MyGlobal.prisma.discussion_board_system_notices.findUniqueOrThrow({
      where: { id: systemNoticeId },
    });

  // 스케줄 윈도우 유효성체크 (start_at <= end_at)
  if (
    body.start_at !== undefined &&
    body.start_at !== null &&
    body.end_at !== undefined &&
    body.end_at !== null &&
    body.start_at > body.end_at
  ) {
    throw new Error(
      `start_at(${body.start_at})은 end_at(${body.end_at})보다 늦을 수 없습니다.`,
    );
  }

  // updated_at은 반드시 현시각(ISO8601 string)
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  const updated = await MyGlobal.prisma.discussion_board_system_notices.update({
    where: { id: systemNoticeId },
    data: {
      category_id: body.category_id ?? undefined,
      title: body.title,
      body: body.body,
      is_active: body.is_active,
      start_at: body.start_at ?? undefined,
      end_at: body.end_at ?? undefined,
      updated_at: now,
    },
  });

  return {
    id: updated.id,
    category_id: updated.category_id ?? null,
    title: updated.title,
    body: updated.body,
    is_active: updated.is_active,
    start_at: updated.start_at ? toISOStringSafe(updated.start_at) : null,
    end_at: updated.end_at ? toISOStringSafe(updated.end_at) : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Permanently deletes a system notice (by UUID) from the database.
 *
 * This operation is restricted to admin users. Deletion is irreversible and
 * will immediately remove the notice from all user views. No soft-delete is
 * supported.
 *
 * @param props - Request parameters
 * @param props.admin - Authenticated admin payload (authorization required)
 * @param props.systemNoticeId - The UUID of the system notice to delete
 * @returns Void (on success)
 * @throws {Error} When notice does not exist (404), or on authorization failure
 */
export async function delete__discussionBoard_admin_systemNotices_$systemNoticeId(props: {
  admin: AdminPayload;
  systemNoticeId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, systemNoticeId } = props;
  // Authorization guaranteed by decorator, but could enforce revoked_at == null if necessary
  try {
    await MyGlobal.prisma.discussion_board_system_notices.delete({
      where: { id: systemNoticeId },
    });
    // Success: returns void (204 No Content expected)
    return;
  } catch (err) {
    // Prisma throws an error if not found - treat as 404
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2025"
    ) {
      throw new Error("System notice not found");
    }
    throw err;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Lists all registered board administrators (including currently active and
 * previously revoked admins).
 *
 * Each record displays id (UUID), user identifier, grant timestamp, and revoke
 * timestamp if revoked. Only platform admins (authorization required) may
 * invoke this endpoint. Results are returned in paginated structure; since no
 * paging parameters are given, all are returned in a single page.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making the request (must be
 *   currently active)
 * @returns Paginated list of board administrator records ({ data:
 *   IDiscussionBoardAdmin[], pagination })
 * @throws {Error} When the caller is not authorized as an admin
 */
export async function get__discussionBoard_admin_admins(props: {
  admin: AdminPayload;
}): Promise<IPageIDiscussionBoardAdmin> {
  const { admin } = props;
  if (!admin) {
    throw new Error("Forbidden: Only admins may access this resource.");
  }

  const admins = await MyGlobal.prisma.discussion_board_admins.findMany({
    orderBy: { granted_at: "desc" },
  });

  const data = admins.map((row) => ({
    id: row.id as string & tags.Format<"uuid">,
    user_identifier: row.user_identifier,
    granted_at: toISOStringSafe(row.granted_at),
    revoked_at:
      row.revoked_at === null || row.revoked_at === undefined
        ? null
        : toISOStringSafe(row.revoked_at),
  }));

  return {
    data,
    pagination: {
      current: 1 as number & tags.Type<"int32">,
      limit: 100 as number & tags.Type<"int32">,
      records: data.length as number & tags.Type<"int32">,
      pages: 1 as number & tags.Type<"int32">,
    },
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Returns a filtered, paginated result set of administrator entities from
 * discussion_board_admins.
 *
 * This endpoint allows system administrators to perform advanced searches over
 * admin assignments for privilege audits, admin activity monitoring, and
 * reporting. Filtering supports searching by user_identifier (case-insensitive
 * partial match), date range windows on granted_at and revoked_at, and
 * paginated navigation.
 *
 * Authorization: Only available to authenticated admins. Returns no data for
 * other users.
 *
 * @param props - Request properties
 * @param props.admin - Verified admin authentication payload (must have active
 *   privileges)
 * @param props.body - Advanced search criteria: user_identifier (partial),
 *   granted_at (from/to), revoked_at (from/to), page, limit
 * @returns Paginated result of administrator entity records matching the
 *   provided filters.
 * @throws {Error} If the authenticated admin record is invalid (should be
 *   impossible with proper middleware)
 */
export async function patch__discussionBoard_admin_admins(props: {
  admin: AdminPayload;
  body: IDiscussionBoardAdmin.IRequest;
}): Promise<IPageIDiscussionBoardAdmin> {
  const { admin, body } = props;

  // Build where clause incrementally using only defined filters
  const where = {
    ...(body.user_identifier !== undefined &&
      body.user_identifier !== null &&
      body.user_identifier.length > 0 && {
        user_identifier: {
          contains: body.user_identifier,
          mode: "insensitive" as const,
        },
      }),
    ...((body.granted_at_from !== undefined && body.granted_at_from !== null) ||
    (body.granted_at_to !== undefined && body.granted_at_to !== null)
      ? {
          granted_at: {
            ...(body.granted_at_from !== undefined &&
              body.granted_at_from !== null && { gte: body.granted_at_from }),
            ...(body.granted_at_to !== undefined &&
              body.granted_at_to !== null && { lte: body.granted_at_to }),
          },
        }
      : {}),
    ...((body.revoked_at_from !== undefined && body.revoked_at_from !== null) ||
    (body.revoked_at_to !== undefined && body.revoked_at_to !== null)
      ? {
          revoked_at: {
            ...(body.revoked_at_from !== undefined &&
              body.revoked_at_from !== null && { gte: body.revoked_at_from }),
            ...(body.revoked_at_to !== undefined &&
              body.revoked_at_to !== null && { lte: body.revoked_at_to }),
          },
        }
      : {}),
  };

  // Pagination: defaults if not provided
  const page = (
    body.page !== undefined && body.page !== null && body.page > 0
      ? body.page
      : 1
  ) as number & tags.Type<"int32">;
  const limit = (
    body.limit !== undefined && body.limit !== null && body.limit > 0
      ? body.limit
      : 100
  ) as number & tags.Type<"int32">;
  const skip = (page - 1) * limit;

  // Query admins with filters and pagination
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_admins.findMany({
      where,
      orderBy: { granted_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_admins.count({
      where,
    }),
  ]);

  // Map results to correct API schema types (convert Date fields to strings)
  return {
    pagination: {
      current: page,
      limit,
      records: total as number & tags.Type<"int32">,
      pages: Math.ceil(total / limit) as number & tags.Type<"int32">,
    },
    data: rows.map((admin) => ({
      id: admin.id,
      user_identifier: admin.user_identifier,
      granted_at: toISOStringSafe(admin.granted_at),
      revoked_at:
        admin.revoked_at !== null && admin.revoked_at !== undefined
          ? toISOStringSafe(admin.revoked_at)
          : null,
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Returns full details for one administrator entity as defined in the
 * discussion_board_admins schema. Exposes id, user_identifier, grant and
 * optional revocation timestamp, supporting permission history, account status,
 * and audit review.
 *
 * Intended for admin owners and compliance/operations staff, e.g. to review a
 * specific admin’s tenure and status. Only available to admins; others denied.
 * Returns 404 if not found.
 *
 * To create, update, or delete admins see relevant endpoints. This is the
 * canonical single-lookup operation.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin making the request (AdminPayload).
 *   Required for authorization.
 * @param props.adminId - UUID (PK) identifying the admin to retrieve. Must
 *   match discussion_board_admins.id field.
 * @returns IDiscussionBoardAdmin object with all details, or throws if not
 *   found.
 * @throws {Error} When the admin record with the given ID does not exist (404)
 */
export async function get__discussionBoard_admin_admins_$adminId(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardAdmin> {
  const { admin, adminId } = props;

  // Prisma returns Date objects, so convert to ISO string using toISOStringSafe()
  const row = await MyGlobal.prisma.discussion_board_admins.findUniqueOrThrow({
    where: { id: adminId },
    select: {
      id: true,
      user_identifier: true,
      granted_at: true,
      revoked_at: true,
    },
  });

  return {
    id: row.id,
    user_identifier: row.user_identifier,
    granted_at: toISOStringSafe(row.granted_at),
    ...(row.revoked_at !== null && row.revoked_at !== undefined
      ? { revoked_at: toISOStringSafe(row.revoked_at) }
      : { revoked_at: null }),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Adds a new administrator to the system as per discussion_board_admins model.
 *
 * This operation adds a new admin record to the discussion_board_admins table,
 * restricted to authenticated active admins. Input must include user_identifier
 * (external ID), granted_at (required as ISO date-time string), and may
 * optionally supply revoked_at. ID is generated as a UUID with v4(). Enforces
 * unique constraint on user_identifier, rejecting duplicate creation attempts
 * with a clear error. Returns the full persisted admin record.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated AdminPayload (enforced via AdminAuth
 *   decorator)
 * @param props.body - Admin creation details (user_identifier, granted_at,
 *   optional revoked_at as ISO string)
 * @returns The newly created admin as IDiscussionBoardAdmin
 * @throws {Error} If user_identifier already exists in the system (unique
 *   violation)
 */
export async function post__discussionBoard_admin_admins(props: {
  admin: AdminPayload;
  body: IDiscussionBoardAdmin.ICreate;
}): Promise<IDiscussionBoardAdmin> {
  const { admin, body } = props;
  try {
    const created = await MyGlobal.prisma.discussion_board_admins.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        user_identifier: body.user_identifier,
        granted_at: body.granted_at,
        revoked_at: body.revoked_at ?? null,
      },
    });
    return {
      id: created.id,
      user_identifier: created.user_identifier,
      granted_at: toISOStringSafe(created.granted_at),
      revoked_at: created.revoked_at
        ? toISOStringSafe(created.revoked_at)
        : null,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new Error("Admin already exists for this user_identifier");
    }
    throw error;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
