/**
 * Updates details for specific admin by ID in discussion_board_admins.
 *
 * Allows changing the user_identifier (e.g., after SSO change), adjusting the
 * grant time, or setting/resetting the revoked time for privilege changes.
 * Audit log is expected to be updated externally.
 *
 * Returns the full admin as updated or throws 404 if the record does not exist.
 * Throws on uniqueness violations of user_identifier.
 *
 * @param props - Request properties
 * @param props.admin - Verified admin making the request (must be active)
 * @param props.adminId - UUID of the admin entity to update
 * @param props.body - Updated assignment info (user_identifier, granted_at,
 *   revoked_at)
 * @returns The updated admin entity
 * @throws {Error} If not found or uniqueness error on user_identifier
 */
export async function put__discussionBoard_admin_admins_$adminId(props: {
