/**
 * Search and filter guest sessions with advanced criteria.
 *
 * Search and filter guest user sessions using detailed criteria. This endpoint
 * enables the querying of guest activity based on parameters such as
 * session_identifier, first_seen/last_seen date ranges, and other analytics
 * requirements. Pagination and sorting options allow for efficient analysis of
 * large datasets.
 *
 * Only administrators and system operators should be able to run detailed
 * analytics on guest session information, as misuse could expose traffic
 * patterns or system metrics considered sensitive. No personal identifiers are
 * stored for guests, aligning with the privacy requirement.
 *
 * Refer to the discussion_board_guests table for all field definitions; all
 * guest analytics or dashboard features must call this endpoint when presenting
 * filtered or paginated results.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the analytics query
 *   (must not be revoked)
 * @param props.body - Filter, pagination, and search parameters for guest
 *   sessions
 * @returns Paginated guest session entity results matching filter/search
 *   criteria
 * @throws {Error} When admin privileges are revoked or invalid
 */
export async function patch__discussionBoard_admin_guests(props: {
  admin: AdminPayload;
  body: IDiscussionBoardGuest.IRequest;
}): Promise<IPageIDiscussionBoardGuest> {
  const { admin, body } = props;
  // Ensure admin privileges and not revoked -- enforced by decorator but double-check contract
  if (admin.revoked_at !== null) {
    throw new Error("Admin privileges have been revoked.");
  }
  const page = body.page ?? 0;
  const limit = body.limit ?? 100;
  const where = {
    ...(body.session_identifier !== undefined &&
      body.session_identifier !== null && {
        session_identifier: body.session_identifier,
      }),
    ...((body.first_seen_at_from !== undefined &&
      body.first_seen_at_from !== null) ||
    (body.first_seen_at_to !== undefined && body.first_seen_at_to !== null)
      ? {
          first_seen_at: {
            ...(body.first_seen_at_from !== undefined &&
              body.first_seen_at_from !== null && {
                gte: body.first_seen_at_from,
              }),
            ...(body.first_seen_at_to !== undefined &&
              body.first_seen_at_to !== null && {
                lte: body.first_seen_at_to,
              }),
          },
        }
      : {}),
    ...((body.last_seen_at_from !== undefined &&
      body.last_seen_at_from !== null) ||
    (body.last_seen_at_to !== undefined && body.last_seen_at_to !== null)
      ? {
          last_seen_at: {
            ...(body.last_seen_at_from !== undefined &&
              body.last_seen_at_from !== null && {
                gte: body.last_seen_at_from,
              }),
            ...(body.last_seen_at_to !== undefined &&
              body.last_seen_at_to !== null && {
                lte: body.last_seen_at_to,
              }),
          },
        }
      : {}),
  };
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_guests.findMany({
      where,
      orderBy: { last_seen_at: "desc" },
      skip: page * limit,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_guests.count({ where }),
  ]);
  const data = rows.map((row) => ({
    id: row.id as string & tags.Format<"uuid">,
    session_identifier: row.session_identifier,
    first_seen_at: toISOStringSafe(row.first_seen_at),
    last_seen_at: toISOStringSafe(row.last_seen_at),
  }));
  const pages = Math.ceil(total / limit);
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: pages,
    },
    data,
  };
}

