  const where = {
    ...(body.actor_type !== undefined &&
      body.actor_type !== null && {
        actor_type: body.actor_type,
      }),
    ...(body.actor_identifier !== undefined &&
      body.actor_identifier !== null && {
        actor_identifier: body.actor_identifier,
      }),
    ...(body.session_token !== undefined &&
      body.session_token !== null && {
        session_token: body.session_token,
      }),
    ...(body.active_only === true && {
      terminated_at: null,
      expires_at: {
        gte: nowIso,
      },
    }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_user_sessions.findMany({
      where,
      orderBy: {
        created_at: "desc",
      },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_user_sessions.count({ where }),
  ]);

  const data = rows.map(
    (row): IDiscussionBoardUserSession => ({
      id: row.id,
      actor_type: row.actor_type,
      actor_identifier: row.actor_identifier,
      session_token: row.session_token,
      created_at: toISOStringSafe(row.created_at),
      expires_at: toISOStringSafe(row.expires_at),
      terminated_at:
        row.terminated_at !== undefined && row.terminated_at !== null
          ? toISOStringSafe(row.terminated_at)
          : null,
    }),
  );

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

