              body.updated_from !== null && {
                gte: body.updated_from,
              }),
            ...(body.updated_to !== undefined &&
              body.updated_to !== null && {
                lte: body.updated_to,
              }),
          },
        }
      : {}),
  };

  // 데이터 쿼리 & 전체 count 동시 수행
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_topics.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip: (page - 1) * limit,
      take: limit,
      select: {
        id: true,
        title: true,
        description: true,
        pinned: true,
        closed: true,
        created_at: true,
        updated_at: true,
        discussion_board_category_id: true,
      },
    }),
    MyGlobal.prisma.discussion_board_topics.count({ where }),
  ]);

  // 결과 매핑 및 Date 변환
  const data = rows.map((row) => ({
    id: row.id,
    title: row.title,
    description: row.description ?? null,
    pinned: row.pinned,
    closed: row.closed,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    discussion_board_category_id: row.discussion_board_category_id,
  }));

  return {
    pagination: {
      current: page,
