/**
 * Permanently delete a specific subscription to stop all future notifications
 * (hard delete; no soft delete field).
 *
 * Only an admin (valid, non-revoked) may invoke this endpoint. The deletion is
 * audit logged for compliance using the discussion_board_audit_logs table. If
 * the subscription does not exist, an error is thrown.
 *
 * @param props - Parameters for the operation
 * @param props.admin - Authenticated admin identity for authorization and audit
 *   logging
 * @param props.subscriptionId - Unique identifier of the subscription to delete
 *   (UUID)
 * @returns Void
 * @throws {Error} If the subscription does not exist
 */
export async function delete__discussionBoard_admin_subscriptions_$subscriptionId(props: {
  admin: AdminPayload;
  subscriptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, subscriptionId } = props;

  // Step 1: Fetch the subscription by id
  const subscription =
    await MyGlobal.prisma.discussion_board_subscriptions.findUnique({
      where: { id: subscriptionId },
    });
  if (!subscription) {
    throw new Error("Subscription not found");
  }

  // Step 2: Delete the subscription (hard delete; there is no soft delete field)
  await MyGlobal.prisma.discussion_board_subscriptions.delete({
    where: { id: subscriptionId },
