/**
 * Retrieves a paginated list of notifications for the authenticated member.
 *
 * This endpoint returns the current user's notifications (both in-app and
 * system/email) from the notifications table, paginated and sorted by delivery
 * date (most recent first). Only the authenticated member may access their
 * notifications; notifications remain private to their owner.
 *
 * Pagination parameters default to page=1, limit=20. If no notifications are
 * found, the data array is empty.
 *
 * @param props - Request properties
 * @param props.member - The authenticated member payload injected via
 *   MemberAuth (must match notification recipient)
 * @returns A paginated object containing the member's notifications
 * @throws {Error} When the recipient does not match the authenticated user
 *   (should never occur)
 */
export async function get__discussionBoard_member_notifications(props: {
  member: MemberPayload;
}): Promise<IPageIDiscussionBoardNotification> {
  const { member } = props;
  // Default pagination
  const page = 1 as number & tags.Type<"int32">;
  const limit = 20 as number & tags.Type<"int32">;

  // Fetch notifications data and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_notifications.findMany({
      where: { recipient_id: member.id },
      orderBy: { delivered_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_notifications.count({
      where: { recipient_id: member.id },
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total as number & tags.Type<"int32">,
      pages: Math.ceil(total / limit) as number & tags.Type<"int32">,
    },
    data: rows.map((row) => ({
      id: row.id,
      recipient_id: row.recipient_id,
      subscription_id: row.subscription_id ?? null,
      notification_type: row.notification_type,
      target_type: row.target_type,
      target_id: row.target_id,
      message: row.message,
      delivered_at: toISOStringSafe(row.delivered_at),
      read_at: row.read_at ? toISOStringSafe(row.read_at) : null,
      delivery_status: row.delivery_status,
      failure_reason: row.failure_reason ?? null,
    })),
  };
}

