}): Promise<IPageIDiscussionBoardNotification> {
  const { member, body } = props;
  if (!member.id) throw new Error("No member id provided");

  // Default paging logic
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 100;

  // Assemble the Prisma WHERE clause with all filters
  const where = {
